#[derive(Clone, Copy, PartialEq)]
enum Mode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

// For error handling with output
struct TransformResult {
    output: String,
    error: Option<String>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files: Vec<String> = Vec::new();
    let mut stop_options = false;
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if !stop_options && a == "--" {
            stop_options = true;
            i+=1;
            continue;
        }
        if !stop_options && a.starts_with("--") {
            match a.as_str() {
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                "--help" => { print_help(); process::exit(0); },
                "--version" => { println!("4.3.1"); process::exit(0); },
                _ => {
                    eprintln!("{}: No such option.", a);
                    process::exit(3);
                }
            }
        } else if !stop_options && a == "-h" {
            print_help();
            process::exit(0);
        } else if !stop_options && a.starts_with("-") && a.len()>1 {
            // unknown short option
            eprintln!("{}: No such option.", a);
            process::exit(3);
        } else {
            files.push(a.clone());
        }
        i+=1;
    }

    let has_stdin_placeholder = files.iter().any(|f| f == "");
    let mut stdin_content: Option<String> = None;
    if has_stdin_placeholder {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        stdin_content = Some(buf);
    }

    if files.is_empty() {
        process::exit(0);
    }

    // Build ordered list of (path, content) handling '' deduplication: only first '' included
    let mut ordered: Vec<(String,String)> = Vec::new();
    let mut stdin_used = false;
    let mut had_file_error = false;
    let mut file_read_errors: Vec<String> = Vec::new();
    for f in &files {
        if f == "" {
            if !stdin_used {
                if let Some(ref c) = stdin_content {
                    ordered.push(("".to_string(), c.clone()));
                } else {
                    ordered.push(("".to_string(), String::new()));
                }
                stdin_used = true;
            }
        } else {
            match fs::read_to_string(f) {
                Ok(c) => ordered.push((f.clone(), c)),
                Err(e) => {
                    // Use same format as original: path: No such file or directory (os error 2)
                    eprintln!("{}: {}", f, e);
                    had_file_error = true;
                    file_read_errors.push(f.clone());
                }
            }
        }
    }

    // Now process each ordered entry
    let mut had_transform_error = false;
    let mut check_needed = false;
    let mut output_parts: Vec<String> = Vec::new();

    for (path, content) in ordered.iter() {
        let res = transform_file(content, mode, path);
        match res {
            Ok(tr) => {
                if let Some(err) = tr.error {
                    // error case: print error to stderr
                    if path == "" {
                        eprintln!("{}", err);
                    } else {
                        eprintln!("{}: {}", path, err);
                    }
                    had_transform_error = true;
                    // For non-check modes, still output what we have (partial)
                    if mode != Mode::Check && mode != Mode::Replace {
                        output_parts.push(tr.output);
                    } else if mode == Mode::Replace {
                        // Don't replace if error? Original still? For pitfall, it outputs partially transformed? But for replace mode, if error, file not replaced? Need to check.
