                    }
                } else {
                    // no error
                    match mode {
                        Mode::Check => {
                            if tr.output != *content {
                                check_needed = true;
                            }
                        },
                        Mode::Replace => {
                            if path != "" && tr.output != *content {
                                let _ = fs::write(path, tr.output);
                            }
                        },
                        _ => {
                            output_parts.push(tr.output);
                        }
                    }
                }
            },
            Err(e) => {
                // This is for unexpected EOF etc that returns Err directly
                if path == "" {
                    eprintln!("{}", e);
                } else {
                    eprintln!("{}: {}", path, e);
                }
                had_transform_error = true;
                // For transform mode, original outputs partially transformed content before error? We need to capture partial.
                // Our transform_file should have returned TransformResult with output even on error, so this branch is for file read errors already handled.
                // For now, skip.
            }
        }
    }

    // Exit codes
    if mode == Mode::Check {
        if had_file_error || had_transform_error {
            process::exit(1);
        }
        if check_needed {
            process::exit(2);
        } else {
            process::exit(0);
        }
    } else {
        if had_file_error || had_transform_error {
            for o in output_parts {
                print!("{}", o);
            }
            process::exit(1);
        } else {
            for o in output_parts {
                print!("{}", o);
            }
            process::exit(0);
        }
    }
}

