        // For simplicity, if word contains = and before = is valid identifier (or identifier with [index]), and we are at command start or after assignment or after export/local etc, then it's assignment

        let is_assignment = is_assignment_word(&word, at_command_start, seen_assignment, after_export_local);

        // Check if word is a keyword that introduces assignments: local, export, declare, typeset, readonly, etc
        let is_assignment_introducer = is_assignment_introducer_word(&word);

        // Check for special handling: case, if, [[, etc
