            // So we set after_export_local flag and leave word as is (but maybe transform its options? For export -n, -n should not be quoted)
            after_export_local = true;
            // Keep word as is, no quoting
            word.clone()
        } else {
            // Check if we are at command start and word is assignment introducer already handled
            // For normal words, transform according to rules
            // Determine if this word is in a context where quoting is not needed (case, [[, etc)
            // We'll call transform_word with assignment context false
            let tw = transform_word(&word, false);
            tw
        };

        // Update flags for next word
        if is_assignment {
            // After assignment, we remain at command start? Actually after assignments, we may still be at command start for more assignments, but once we see a non-assignment word, we are no longer at command start
            seen_assignment = true;
            // at_command_start remains true until we see non-assignment
        } else if is_assignment_introducer {
            // after introducer, we are still expecting assignments, so at_command_start remains true? Actually after local/export, we expect assignments or options
            // For simplicity, keep at_command_start true and set after_export_local
            at_command_start = true;
            seen_assignment = false;
        } else {
            // Non-assignment word, so we are no longer at command start (except after separators)
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
        }

        out.push_str(&transformed_word);
        i = word_end;
    }

    out
}

fn is_assignment_word(word: &str, at_command_start: bool, seen_assignment: bool, after_export_local: bool) -> bool {
    // Must contain = not at beginning, and identifier before =
    if !word.contains('=') {
        return false;
    }
    if !at_command_start && !seen_assignment && !after_export_local {
        return false;
    }
    // Handle cases like VAR=, VAR=foo, VAR+=foo, VAR[0]=foo, VAR+= etc
    // For array assignment: ARR=(...), contains = and ( after, but still assignment
    // For simplicity, check if word starts with identifier (possibly with [index] or +) then =
    // Find position of =
    if let Some(eq_pos) = word.find('=') {
        if eq_pos == 0 {
            return false;
        }
        let before = &word[..eq_pos];
        // Handle +=: before may end with +
        let mut base = before;
        if base.ends_with('+') {
            base = &base[..base.len()-1];
        }
        // Check for array index: VAR[0]
        // If contains [ and ], extract base identifier before [
        let mut identifier = base;
        if let Some(bracket_pos) = base.find('[') {
            identifier = &base[..bracket_pos];
            // check that after [ there's ] and nothing else? For our purposes, it's still assignment
        }
        // identifier must be valid
        if identifier.is_empty() {
            return false;
        }
        // First char must be alpha or _
        if !is_identifier_start(identifier.chars().next().unwrap()) {
            return false;
        }
        // Rest must be identifier chars
        if !identifier.chars().all(|c| is_identifier_char(c)) {
            return false;
        }
        true
    } else {
        false
    }
}

fn is_assignment_introducer_word(word: &str) -> bool {
    matches!(word, "local" | "export" | "declare" | "typeset" | "readonly" | "unset")
}

fn transform_assignment_word(word: &str) -> String {
    // Assignment word like VAR=$VAR or VAR=$VAR:$OTHER etc should not be quoted
    // But if RHS is array like ARR=($VAR) then inside parentheses we should transform
    // Find = position
    if let Some(eq_pos) = word.find('=') {
        let lhs = &word[..eq_pos+1]; // includes =
        let rhs = &word[eq_pos+1..];
        // If rhs starts with '(' and ends with ')' (array), transform inside
        if rhs.starts_with('(') && rhs.ends_with(')') && rhs.len()>=2 {
            let inside = &rhs[1..rhs.len()-1];
            // inside may contain multiple words separated by spaces, each should be transformed
            // Split inside by whitespace, transform each word (as normal word)
            let mut transformed_inside = String::new();
            // For simplicity, split by whitespace and transform
            // But need to preserve original spacing? We'll preserve single space between
            let parts: Vec<&str> = inside.split_whitespace().collect();
            for (idx, part) in parts.iter().enumerate() {
                if idx>0 {
                    transformed_inside.push(' ');
                }
                // For array assignment, transform part as normal word, but it may contain $VAR etc that should be quoted
                transformed_inside.push_str(&transform_word(part, false));
            }
            // If original had no spaces? We'll just use transformed
            return format!("{}({})", lhs, transformed_inside);
        } else {
            // Scalar assignment: leave RHS as is (no quoting)
            // However, what about RHS that is "$VAR"? Already quoted, leave as is
            // So return word unchanged
            return word.to_string();
        }
    }
    word.to_string()
}

