fn transform_var_token(raw: &str) -> (String, bool) {
    // raw like "$VAR", "${VAR}", "$*", "$@", "$1", "${VAR[@]}", "${VAR[*]}", "$?", "$$", etc
    // Returns (replacement_inside_quotes, needs_quotes)
    // needs_quotes false means does not need quoting (e.g., $?, $$, $#, $!, ${#VAR}, $((...)), etc)

    // Handle ${...}
    if raw.starts_with("${") && raw.ends_with('}') {
        let inner = &raw[2..raw.len()-1];
        // Handle ${#VAR} and ${#VAR[@]}
        if inner.starts_with('#') {
            // ${#VAR}, ${#VAR[@]}, ${#} etc - no quoting needed
            return (raw.to_string(), false);
        }
        // Handle ${VAR[@]}, ${VAR[*]}
        if inner.ends_with("[@]") {
            // ${VAR[@]} stays "${VAR[@]}" -> inside quotes it's ${VAR[@]} but needs quotes? Actually ${VAR[@]} already requires quotes to preserve array, so needs quotes
            // For transform, ${VAR[@]} should become "${VAR[@]}" (quoted)
            // So replacement inside quotes is ${VAR[@]} (without outer quotes)
            return (raw.to_string(), true);
        }
        if inner.ends_with("[*]") {
            // ${VAR[*]} -> ${VAR[@]} (convert * to @)
            let base = &inner[..inner.len()-3];
            let new_inner = format!("{}[@]", base);
            let new_raw = format!("${{{}}}", new_inner);
            return (new_raw, true);
        }
        // Handle ${VAR:0:1}, ${VAR:-default}, etc - these need quotes
        // For simple ${VAR}, we can convert to $VAR (remove braces)
        if is_simple_identifier(inner) {
            return (format!("${}", inner), true);
        }
        // For more complex like ${VAR:-default}, keep as is but needs quotes
        // Also ${VAR:-$OTHER} inner contains $OTHER which should have been transformed? But for now keep raw
        return (raw.to_string(), true);
    }

    // Handle $((...)) arithmetic - no quotes
    if raw.starts_with("$((") {
        return (raw.to_string(), false);
    }

    // Handle $(...) command substitution
    if raw.starts_with("$(") && raw.ends_with(')') {
        // Transform inside recursively
        let inner = &raw[2..raw.len()-1];
        // Transform inner code (simple)
        let transformed_inner = do_transform(inner);
        let new_raw = format!("$({})", transformed_inner.trim());
        // Command substitution needs quotes: "$(...)"
        // Replacement inside quotes is $(...)
        return (new_raw, true);
    }

    // Handle backticks `...`
    if raw.starts_with('`') && raw.ends_with('`') && raw.len()>=2 {
        // Transform inside
        let inner = &raw[1..raw.len()-1];
        let transformed_inner = do_transform(inner);
        // Backticks should be converted to $(...) per shellharden behavior: rewrites into dollar-parenthesis form when quotes needed
        // We observed: echo `ls $HOME` -> "$(ls "$HOME")" (converted to $() and quoted)
        // var=`ls $HOME` stays `ls "$HOME"` (not converted? Actually we saw var=`ls $HOME` stays backticks? Let's check earlier: var=`ls $HOME` -> var=`ls "$HOME"` (stays backticks, not converted). So conversion depends on context? In command substitution as argument, it converts to $(), but in assignment it stays backticks.
        // For simplicity, convert backticks to $() always when need quotes
        let new_raw = format!("$({})", transformed_inner.trim());
        return (new_raw, true);
    }

    // Handle $*, $@, $#, $?, $$, $!, $-, $0, $1..$9
    if raw.len() == 2 && "*@#?$!-$".contains(raw.chars().nth(1).unwrap()) {
        let ch = raw.chars().nth(1).unwrap();
        match ch {
            '*' => {
                // $* -> $@ (inside quotes, it's $@)
                return ("$@".to_string(), true);
            },
            '@' => {
                return ("$@".to_string(), true);
            },
            '#' | '?' | '!' | '$' => {
                // numeric or special that doesn't need quotes
                return (raw.to_string(), false);
            },
            '-' => {
                return (raw.to_string(), false);
            },
            _ => {
                return (raw.to_string(), false);
            }
        }
    }

    // Handle $1..$9
    if raw.len() == 2 && raw.chars().nth(1).unwrap().is_ascii_digit() {
        // $1..$9 needs quotes: "$1"
        return (raw.to_string(), true);
    }

    // Handle $VAR
    if raw.starts_with('$') {
        let rest = &raw[1..];
        if !rest.is_empty() && is_identifier_start(rest.chars().next().unwrap()) {
            // $VAR
            return (raw.to_string(), true);
        }
    }

    // Fallback: treat as literal that doesn't need quotes? But it is var, so needs quotes
    (raw.to_string(), true)
}

fn find_matching_brace(chars: &[char], open_pos: usize) -> Option<usize> {
    // open_pos points to '{'
    let mut depth = 0;
    for (idx, &c) in chars.iter().enumerate().skip(open_pos) {
        if c == '{' {
            depth+=1;
        } else if c == '}' {
            depth-=1;
            if depth==0 {
                return Some(idx);
            }
        }
    }
    None
}

fn find_matching_brace_in_chars(chars: &[char], open_pos: usize) -> Option<usize> {
    find_matching_brace(chars, open_pos)
}

