                i+=2; at_line_start = false; continue;
            }
            if is_identifier_start(next) {
                let mut j = i+1;
                while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
                let s: String = chars[i..j].iter().collect();
                out.push_str("\x1b[0;38;2;63;127;207m"); out.push_str(&s); out.push_str("\x1b[m");
                i = j; at_line_start = false; continue;
            }
        }
        if c.is_alphabetic() {
            let mut j = i;
            while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') { j+=1; }
            let w: String = chars[i..j].iter().collect();
            if matches!(w.as_str(), "if" | "then" | "else" | "elif" | "fi" | "for" | "in" | "do" | "done" | "case" | "esac" | "while" | "until" | "function" | "select" | "time" | "local" | "export" | "declare" | "typeset" | "readonly") {
                out.push_str("\x1b[0;1m"); out.push_str(&w); out.push_str("\x1b[m");
                i = j; at_line_start = false; continue;
            }
            if at_line_start {
                out.push_str("\x1b[0;38;2;192;0;128m"); out.push_str(&w); out.push_str("\x1b[m");
                i = j; at_line_start = false; continue;
            }
        }
        if is_identifier_start(c) {
            let mut j = i;
            while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
