            i+=1;
            if i < chars.len() {
                let nc = chars[i];
                if (c == '&' && nc == '&') || (c == '|' && nc == '|') { out.push(nc); i+=1; }
                else if c == '[' && nc == '[' { out.push(nc); i+=1; in_double_bracket = true; }
                else if c == ']' && nc == ']' { out.push(nc); i+=1; in_double_bracket = false; }
            }
            continue;
        }
        if c.is_whitespace() { out.push(c); i+=1; continue; }
        let mut j = i;
        let mut w_in_single = false;
        let mut w_in_double = false;
        let mut w_in_ansi = false;
        let mut w_esc = false;
        let mut w_in_backtick = false;
