                        group_vars.push(next_var);
                        j+=2; continue;
                    } else { break; }
                } else { break; }
            } else {
                if !lit_tok.needs_quotes { break; }
                if tok.is_star { break; }
                group_lits.push("".to_string());
                group_vars.push(lit_tok);
                j+=1; continue;
            }
        }
        output.push_str("\\x1b[0;42m\"\\x1b[m");
        for k in 0..group_vars.len() {
            let gv = group_vars[k];
            if gv.original.starts_with("${") && gv.replacement.starts_with('$') && !gv.replacement.contains('{') && gv.is_braced {
                output.push('$');
                output.push_str("\\x1b[0;41m{\\x1b[m");
                output.push_str(&gv.brace_inner);
                output.push_str("\\x1b[0;41m}\\x1b[m");
