                let is_glob = lit.contains('*') || lit.contains('?');
                transformed_tokens.push(Transformed { original: lit.clone(), replacement: lit.clone(), needs_quotes: false, is_var: false, is_glob, is_star: false, is_braced: false, brace_inner: "".to_string() });
