                    output.push_str("]}");
                } else {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\x1b[m");
                    output.push_str("]}");
                }
            } else if gv.is_star {
                output.push('$');
                if k == group_vars.len()-1 {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\"\x1b[m");
                } else {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\x1b[m");
