}

#[derive(Clone, Copy, PartialEq)]
enum Mode { Suggest, Syntax, SyntaxSuggest, Transform, Check, Replace }

struct TransformResult { output: String, error: Option<String> }

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files: Vec<String> = Vec::new();
    let mut stop_options = false;
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if !stop_options && a == "--" { stop_options = true; i+=1; continue; }
        if !stop_options && a.starts_with("--") {
            match a.as_str() {
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                "--help" => { print_help(); process::exit(0); },
                "--version" => { println!("4.3.1"); process::exit(0); },
                _ => { eprintln!("{}: No such option.", a); process::exit(3); }
            }
        } else if !stop_options && a == "-h" { print_help(); process::exit(0); }
        else if !stop_options && a.starts_with("-") && a.len()>1 { eprintln!("{}: No such option.", a); process::exit(3); }
        else { files.push(a.clone()); }
        i+=1;
    }
    let has_stdin_placeholder = files.iter().any(|f| f == "");
    let mut stdin_content: Option<String> = None;
    if has_stdin_placeholder { let mut buf = String::new(); let _ = io::stdin().read_to_string(&mut buf); stdin_content = Some(buf); }
    if files.is_empty() { process::exit(0); }
    let mut ordered: Vec<(String,String)> = Vec::new();
    let mut stdin_used = false;
    let mut had_file_error = false;
    for f in &files {
        if f == "" {
            if !stdin_used {
                if let Some(ref c) = stdin_content { ordered.push(("".to_string(), c.clone())); } else { ordered.push(("".to_string(), String::new())); }
                stdin_used = true;
            }
        } else {
            match fs::read_to_string(f) {
                Ok(c) => ordered.push((f.clone(), c)),
                Err(e) => { eprintln!("{}: {}", f, e); had_file_error = true; }
            }
        }
    }
    let mut had_transform_error = false;
    let mut check_needed = false;
    let mut output_parts: Vec<String> = Vec::new();
    for (path, content) in ordered.iter() {
        let res = transform_file(content, mode, path);
        match res {
            Ok(tr) => {
                if let Some(err) = tr.error {
                    if path == "" { eprintln!("{}", err); } else { eprintln!("{}: {}", path, err); }
                    had_transform_error = true;
                    if mode != Mode::Check && mode != Mode::Replace { output_parts.push(tr.output); }
                } else {
                    match mode {
                        Mode::Check => { if tr.output != *content { check_needed = true; } },
                        Mode::Replace => { if path != "" && tr.output != *content { let _ = fs::write(path, tr.output); } },
                        _ => { output_parts.push(tr.output); }
                    }
                }
            },
            Err(e) => {
                if path == "" { eprintln!("{}", e); } else { eprintln!("{}: {}", path, e); }
                had_transform_error = true;
            }
        }
    }
    if mode == Mode::Check {
        if had_file_error || had_transform_error { process::exit(1); }
        if check_needed { process::exit(2); } else { process::exit(0); }
    } else {
        if had_file_error || had_transform_error {
            for o in output_parts { print!("{}", o); }
            process::exit(1);
        } else {
            for o in output_parts { print!("{}", o); }
            process::exit(0);
        }
    }
}

fn transform_file(content: &str, mode: Mode, _path: &str) -> Result<TransformResult, String> {
    if let Err(e) = check_unclosed(content) {
        let transformed = do_transform(content);
        let out = match mode {
            Mode::Transform => transformed.clone(),
            Mode::Suggest => suggest_diff(content, &transformed),
            Mode::Syntax => syntax_highlight(content).unwrap_or(transformed.clone()),
            Mode::SyntaxSuggest => syntax_highlight_with_suggest(content, &transformed).unwrap_or(transformed.clone()),
            _ => transformed.clone(),
        };
        return Ok(TransformResult { output: out, error: Some(e) });
    }
    if let Some(err) = check_pitfall(content) {
        let transformed = do_transform_with_pitfall(content);
        let out = match mode {
            Mode::Transform => transformed.clone(),
            Mode::Suggest => suggest_diff(content, &transformed),
            Mode::Syntax => syntax_highlight(content).unwrap_or(transformed.clone()),
            Mode::SyntaxSuggest => syntax_highlight_with_suggest(content, &transformed).unwrap_or(transformed.clone()),
            _ => transformed.clone(),
        };
        return Ok(TransformResult { output: out, error: Some(err) });
    }
    let transformed = do_transform(content);
    let out = match mode {
        Mode::Transform => transformed.clone(),
        Mode::Suggest => suggest_diff(content, &transformed),
        Mode::Syntax => syntax_highlight(content).unwrap_or(content.to_string()),
        Mode::SyntaxSuggest => syntax_highlight_with_suggest(content, &transformed).unwrap_or(content.to_string()),
        Mode::Check => transformed.clone(),
        Mode::Replace => transformed.clone(),
    };
    Ok(TransformResult { output: out, error: None })
}

fn check_unclosed(content: &str) -> Result<(), String> {
    let bytes = content.as_bytes();
    let mut i = 0;
    let mut in_single = false;
    let mut in_double = false;
    let mut in_ansi = false;
    let mut escaped = false;
    let mut stack: Vec<String> = Vec::new();
    let mut heredoc_delims: Vec<String> = Vec::new();
    while i < bytes.len() {
        let c = bytes[i] as char;
        if escaped { escaped = false; i+=1; continue; }
        if c == '\\' && !in_single { escaped = true; i+=1; continue; }
        if in_single { if c == '\'' { in_single = false; } i+=1; continue; }
        if in_ansi { if c == '\'' { in_ansi = false; } i+=1; continue; }
        if in_double { if c == '"' { in_double = false; } i+=1; continue; }
        if c == '\'' {
            if i>0 && bytes[i-1] as char == '$' { in_ansi = true; } else { in_single = true; }
            i+=1; continue;
        }
        if c == '"' { in_double = true; i+=1; continue; }
        if c == '`' {
            if stack.last().map_or(false, |s| s == "`") { stack.pop(); } else { stack.push("`".to_string()); }
            i+=1; continue;
        }
        if c == '$' && i+1 < bytes.len() {
            let n = bytes[i+1] as char;
            if n == '(' {
                if i+2 < bytes.len() && bytes[i+2] as char == '(' { stack.push("((".to_string()); i+=3; continue; }
                else { stack.push("$(".to_string()); i+=2; continue; }
            } else if n == '{' { stack.push("${".to_string()); i+=2; continue; }
        }
        if c == ')' {
            if stack.last().map_or(false, |s| s == "$(") { stack.pop(); }
            else if stack.last().map_or(false, |s| s == "((") {
                if i+1 < bytes.len() && bytes[i+1] as char == ')' { stack.pop(); i+=2; continue; }
            }
            i+=1; continue;
        }
        if c == '}' {
            if stack.last().map_or(false, |s| s == "${") { stack.pop(); }
            i+=1; continue;
        }
        if c == '<' && i+1 < bytes.len() && bytes[i+1] as char == '<' {
            let mut j = i+2;
            while j < bytes.len() && (bytes[j] as char == '<' || bytes[j] as char == '-' || bytes[j] as char == ' ' || bytes[j] as char == '\t') { j+=1; }
            let start = j;
            while j < bytes.len() && !(bytes[j] as char).is_whitespace() { j+=1; }
            if start < j {
                let mut delim = String::from_utf8(bytes[start..j].to_vec()).unwrap_or_default();
                delim = delim.trim_matches('\'').trim_matches('"').trim_matches('`').to_string();
                if !delim.is_empty() { heredoc_delims.push(delim); }
            }
            i = j; continue;
        }
        i+=1;
    }
    if in_single || in_double || in_ansi || !stack.is_empty() {
        return Err("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.".to_string());
    }
    if !heredoc_delims.is_empty() {
        let lines: Vec<&str> = content.lines().collect();
        for delim in heredoc_delims {
            let mut found = false;
            for line in &lines { if line.trim() == delim { found = true; break; } }
            if !found { return Err("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.".to_string()); }
        }
    }
    Ok(())
}

fn check_pitfall(content: &str) -> Option<String> {
    let bytes = content.as_bytes();
    let mut i = 0;
    let mut in_single = false;
    let mut in_ansi = false;
    let mut escaped = false;
    let mut in_double = false;
    while i < bytes.len() {
        let c = bytes[i] as char;
        if escaped { escaped = false; i+=1; continue; }
        if c == '\\' && !in_single { escaped = true; i+=1; continue; }
        if in_single { if c == '\'' { in_single = false; } i+=1; continue; }
        if in_ansi { if c == '\'' { in_ansi = false; } i+=1; continue; }
        if in_double {
            if c == '"' { in_double = false; i+=1; continue; }
            if c == '$' && i+2 < bytes.len() {
                if (bytes[i+1] as char).is_ascii_digit() && (bytes[i+2] as char).is_ascii_digit() {
                    return Some(make_pitfall_msg(content, i));
                }
            }
            i+=1; continue;
        }
        if c == '\'' {
            if i>0 && bytes[i-1] as char == '$' { in_ansi = true; } else { in_single = true; }
            i+=1; continue;
        }
        if c == '"' { in_double = true; i+=1; continue; }
        if c == '#' {
            if i==0 || bytes[i-1] == b' ' || bytes[i-1] == b'\t' || bytes[i-1] == b'\n' || bytes[i-1] == b';' {
                while i < bytes.len() && bytes[i] != b'\n' { i+=1; } continue;
            }
        }
        if c == '$' && i+2 < bytes.len() {
            if (bytes[i+1] as char).is_ascii_digit() && (bytes[i+2] as char).is_ascii_digit() {
                return Some(make_pitfall_msg(content, i));
            }
        }
        i+=1;
    }
    None
}

fn make_pitfall_msg(content: &str, pos: usize) -> String {
    let line_start = content[..pos].rfind('\n').map(|p| p+1).unwrap_or(0);
    let line_end = content[pos..].find('\n').map(|p| pos+p).unwrap_or(content.len());
    let line = &content[line_start..line_end];
    let col = pos - line_start;
    let mut msg = String::new();
    msg.push_str("Unsupported syntax: Syntactic pitfall\n");
    msg.push_str(line); msg.push_str("\n");
    msg.push_str(&" ".repeat(col)); msg.push_str("^^^\n");
    msg.push_str("\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\n");
    msg.push_str("Try this and be shocked: f() { echo \"$9\" \"$10\"; }; f a b c d e f g h i j\n\n");
    msg.push_str("Here is where braces should be used to disambiguate, e.g. \"${10}\" vs \"${1}0\".\n\n");
    msg.push_str("Syntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.");
    msg
}

fn is_identifier_char(c: char) -> bool { c.is_ascii_alphanumeric() || c == '_' }
fn is_identifier_start(c: char) -> bool { c.is_ascii_alphabetic() || c == '_' }
fn is_simple_identifier(s: &str) -> bool {
    if s.is_empty() { return false; }
    let mut chars = s.chars();
    let first = chars.next().unwrap();
    if !is_identifier_start(first) { return false; }
    for ch in chars { if !is_identifier_char(ch) { return false; } }
    true
}

fn do_transform(content: &str) -> String {
    let mut out = String::new();
    for line in content.split_inclusive('\n') {
        let has_nl = line.ends_with('\n');
        let line_content = if has_nl { &line[..line.len()-1] } else { line };
        out.push_str(&transform_line(line_content));
        if has_nl { out.push('\n'); }
    }
    out
}

fn transform_line(line: &str) -> String {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut comment_start: Option<usize> = None;
    for (idx, c) in line.chars().enumerate() {
        if escaped { escaped = false; continue; }
        if c == '\\' && !in_single { escaped = true; continue; }
        if in_single { if c == '\'' { in_single = false; } continue; }
        if in_double { if c == '"' { in_double = false; } continue; }
        if c == '\'' { in_single = true; continue; }
        if c == '"' { in_double = true; continue; }
        if c == '#' {
            if idx==0 { comment_start = Some(idx); break; }
            else {
                let prev = line.chars().nth(idx-1).unwrap_or(' ');
                if prev.is_whitespace() || prev == ';' || prev == '&' || prev == '|' || prev == '(' {
                    comment_start = Some(idx); break;
                }
            }
        }
    }
    let (code_part, comment_part) = if let Some(cs) = comment_start {
        (&line[..cs], &line[cs..])
    } else { (line, "") };
    let trimmed = code_part.trim_start();
    if trimmed.starts_with("for ") || trimmed.starts_with("for\t") {
        if let Some(in_pos) = code_part.find(" in ") {
            let before_in = &code_part[..in_pos+4];
            let after_in = &code_part[in_pos+4..];
            let mut end_pos = after_in.len();
            if let Some(semi) = after_in.find(';') { end_pos = semi; }
            if let Some(do_pos) = after_in.find(" do") { if do_pos < end_pos { end_pos = do_pos; } }
            let words_part = &after_in[..end_pos];
            let rest = &after_in[end_pos..];
            let transformed_words = transform_for_in_words(words_part);
            let transformed_rest = transform_code_part(rest);
            return format!("{}{}{}", before_in, transformed_words, transformed_rest) + comment_part;
        }
    }
    format!("{}{}", transform_code_part(code_part), comment_part)
}

fn transform_for_in_words(words_str: &str) -> String {
    let mut out = String::new();
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    for c in words_str.chars() {
        if c.is_whitespace() {
            if !cur.is_empty() { tokens.push(cur.clone()); cur.clear(); }
            if tokens.last().map_or(true, |t| !t.chars().all(|ch| ch.is_whitespace())) {
                tokens.push(c.to_string());
            } else {
                tokens.last_mut().unwrap().push(c);
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() { tokens.push(cur); }
    for tok in tokens {
        if tok.chars().all(|c| c.is_whitespace()) { out.push_str(&tok); }
        else { out.push_str(&transform_word_for_in(&tok)); }
    }
    out
}

fn transform_word_for_in(word: &str) -> String {
    if word.starts_with('$') && !word.contains('/') && !word.contains(':') && !word.contains('*') && !word.contains('?') {
        if let Some(var_name) = parse_simple_var(word) {
            if var_name == "*" || var_name == "@" { return "\"$@\"".to_string(); }
            if !var_name.contains('{') && !var_name.contains('}') {
                return format!("\"${{{}[@]}}\"", var_name);
            }
        }
        if word.starts_with("${") && word.ends_with('}') {
            let inner = &word[2..word.len()-1];
            if inner.ends_with("[@]") { return format!("\"{}\"", word); }
            else if inner.ends_with("[*]") {
                let base = inner.trim_end_matches("[*]");
                return format!("\"${{{}[@]}}\"", base);
            } else if is_simple_identifier(inner) {
                return format!("\"${}\"", inner);
            }
        }
    }
    transform_word(word, false)
}

fn parse_simple_var(word: &str) -> Option<String> {
    if word.len() < 2 || !word.starts_with('$') { return None; }
    let rest = &word[1..];
    if rest.len() == 1 {
        let c = rest.chars().next().unwrap();
        if "*@#?$!".contains(c) || c.is_ascii_digit() { return Some(rest.to_string()); }
    }
    let mut chars = rest.chars();
    let first = chars.next()?;
    if !is_identifier_start(first) { return None; }
    let mut name = String::new(); name.push(first);
    for ch in chars { if is_identifier_char(ch) { name.push(ch); } else { return None; } }
    Some(name)
}

fn transform_code_part(code: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    let mut at_command_start = true;
    let mut seen_assignment = false;
    let mut after_export_local = false;
    let mut in_single = false;
    let mut in_double = false;
    let mut in_ansi = false;
    let mut escaped = false;
    let mut in_double_bracket = false;
    let mut case_next_no_quote = false;
    while i < chars.len() {
        let c = chars[i];
        if escaped { out.push(c); escaped = false; i+=1; continue; }
        if c == '\\' && !in_single { out.push(c); escaped = true; i+=1; continue; }
        if in_single { out.push(c); if c == '\'' { in_single = false; } i+=1; continue; }
        if in_ansi { out.push(c); if c == '\'' { in_ansi = false; } i+=1; continue; }
        if in_double {
            if c == '"' { out.push(c); in_double = false; i+=1; continue; }
            if c == '$' && i+1 < chars.len() {
                let n = chars[i+1];
                if n == '{' {
                    if let Some(end) = find_matching_brace(&chars, i+1) {
                        let inner: String = chars[i+2..end].iter().collect();
                        if is_simple_identifier(&inner) {
                            out.push_str(&format!("${}", inner));
                        } else {
                            out.push_str(&format!("${{{}}}", inner));
                        }
                        i = end+1; continue;
                    }
                } else if n == '(' {
                    if i+2 < chars.len() && chars[i+2] == '(' {
                        let mut j = i+3;
                        let mut depth = 1;
                        while j < chars.len() {
                            if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                            if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                            j+=1;
                        }
                        let s: String = chars[i..j.min(chars.len())].iter().collect();
                        out.push_str(&s);
                        i = j; continue;
                    } else {
                        let mut j = i+2;
                        let mut depth = 1;
                        let mut in_s=false; let mut in_d=false; let mut esc=false;
                        while j < chars.len() {
                            let ch = chars[j];
                            if esc { esc=false; j+=1; continue; }
                            if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                            if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                            if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                            if ch == '\'' { in_s=true; j+=1; continue; }
                            if ch == '"' { in_d=true; j+=1; continue; }
                            if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                            j+=1;
                        }
                        let inner_cmd = if j > i+2 { chars[i+2..j-1].iter().collect::<String>() } else { "".to_string() };
                        let transformed_inner = do_transform(&inner_cmd);
                        out.push_str(&format!("$({})", transformed_inner.trim()));
                        i = j; continue;
                    }
                } else {
                    out.push(c); i+=1;
                    if i < chars.len() {
                        let nc = chars[i];
                        if "*@#?$!".contains(nc) || nc.is_ascii_digit() { out.push(nc); i+=1; }
                        else if is_identifier_start(nc) {
                            while i < chars.len() && is_identifier_char(chars[i]) { out.push(chars[i]); i+=1; }
                        }
                    }
                    continue;
                }
            }
            out.push(c); i+=1; continue;
        }
        if c == '\'' {
            if i>0 && chars[i-1] == '$' { out.push(c); in_ansi = true; }
            else { out.push(c); in_single = true; }
            i+=1; continue;
        }
        if c == '"' { out.push(c); in_double = true; i+=1; continue; }
        if c == ';' || c == '&' || c == '|' || c == '(' || c == ')' {
            out.push(c); at_command_start = true; seen_assignment = false; after_export_local = false;
            if c == '[' && i+1 < chars.len() && chars[i+1] == '[' { out.push(chars[i+1]); i+=2; in_double_bracket = true; continue; }
            if c == ']' && i+1 < chars.len() && chars[i+1] == ']' { out.push(chars[i+1]); i+=2; in_double_bracket = false; continue; }
            i+=1;
            if i < chars.len() {
                let nc = chars[i];
                if (c == '&' && nc == '&') || (c == '|' && nc == '|') { out.push(nc); i+=1; }
                else if c == '[' && nc == '[' { out.push(nc); i+=1; in_double_bracket = true; }
                else if c == ']' && nc == ']' { out.push(nc); i+=1; in_double_bracket = false; }
            }
            continue;
        }
        if c.is_whitespace() { out.push(c); i+=1; continue; }
        let mut j = i;
        let mut w_in_single = false;
        let mut w_in_double = false;
        let mut w_in_ansi = false;
        let mut w_esc = false;
        let mut w_in_backtick = false;
        let mut w_stack: Vec<String> = Vec::new();
        while j < chars.len() {
            let ch = chars[j];
            if w_esc { w_esc = false; j+=1; continue; }
            if ch == '\\' && !w_in_single { w_esc = true; j+=1; continue; }
            if w_in_single { if ch == '\'' { w_in_single = false; } j+=1; continue; }
            if w_in_ansi { if ch == '\'' { w_in_ansi = false; } j+=1; continue; }
            if w_in_double { if ch == '"' { w_in_double = false; } j+=1; continue; }
            if w_in_backtick { if ch == '`' { w_in_backtick = false; } j+=1; continue; }
            if !w_stack.is_empty() {
                if ch == '\'' { w_in_single = true; j+=1; continue; }
                if ch == '"' { w_in_double = true; j+=1; continue; }
                if ch == '`' { w_in_backtick = true; j+=1; continue; }
                if ch == '$' && j+1 < chars.len() {
                    let n = chars[j+1];
                    if n == '(' {
                        if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                        else { w_stack.push("$(".to_string()); j+=2; continue; }
                    } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
                }
                if ch == ')' {
                    if w_stack.last().map_or(false, |s| s == "$(") { w_stack.pop(); j+=1; continue; }
                    else if w_stack.last().map_or(false, |s| s == "((") {
                        if j+1 < chars.len() && chars[j+1] == ')' { w_stack.pop(); j+=2; continue; }
                    }
                }
                if ch == '}' {
                    if w_stack.last().map_or(false, |s| s == "${") { w_stack.pop(); j+=1; continue; }
                }
                j+=1; continue;
            }
            if ch == '\'' {
                if j>0 && chars[j-1] == '$' { w_in_ansi = true; } else { w_in_single = true; }
                j+=1; continue;
            }
            if ch == '"' { w_in_double = true; j+=1; continue; }
            if ch == '`' { w_in_backtick = true; j+=1; continue; }
            if ch == '$' && j+1 < chars.len() {
                let n = chars[j+1];
                if n == '(' {
                    if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                    else { w_stack.push("$(".to_string()); j+=2; continue; }
                } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
            }
            if ch.is_whitespace() || ch == ';' || ch == '&' || ch == '|' || ch == '(' || ch == ')' || ch == '<' || ch == '>' { break; }
            j+=1;
        }
        let word: String = chars[i..j].iter().collect();
        if word == "case" {
            case_next_no_quote = true;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if word == "[[" {
            in_double_bracket = true;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if word == "]]" {
            in_double_bracket = false;
            out.push_str(&word);
            i = j;
            at_command_start = true;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if case_next_no_quote {
            case_next_no_quote = false;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if in_double_bracket {
            out.push_str(&word);
            i = j;
            if word.contains("]]") { in_double_bracket = false; at_command_start = true; }
            continue;
        }
        let is_assignment = is_assignment_word(&word, at_command_start, seen_assignment, after_export_local);
        let is_introducer = is_assignment_introducer_word(&word);
        let transformed_word = if is_assignment { transform_assignment_word(&word) }
        else if is_introducer { after_export_local = true; word.clone() }
        else { transform_word(&word, false) };
        if is_assignment { seen_assignment = true; }
        else if is_introducer { at_command_start = true; seen_assignment = false; }
        else { at_command_start = false; seen_assignment = false; after_export_local = false; }
        out.push_str(&transformed_word);
        i = j;
    }
    out
}

fn is_assignment_word(word: &str, at_command_start: bool, seen_assignment: bool, after_export_local: bool) -> bool {
    if !word.contains('=') { return false; }
    if !at_command_start && !seen_assignment && !after_export_local { return false; }
    if let Some(eq_pos) = word.find('=') {
        if eq_pos==0 { return false; }
        let mut before = &word[..eq_pos];
        if before.ends_with('+') { before = &before[..before.len()-1]; }
        let mut identifier = before;
        if let Some(bp) = before.find('[') { identifier = &before[..bp]; }
        if identifier.is_empty() { return false; }
        let first = identifier.chars().next().unwrap();
        if !is_identifier_start(first) { return false; }
        if !identifier.chars().all(|c| is_identifier_char(c)) { return false; }
        true
    } else { false }
}

fn is_assignment_introducer_word(word: &str) -> bool {
    matches!(word, "local" | "export" | "declare" | "typeset" | "readonly")
}

fn transform_assignment_word(word: &str) -> String {
    if let Some(eq_pos) = word.find('=') {
        let lhs = &word[..eq_pos+1];
        let rhs = &word[eq_pos+1..];
        if rhs.starts_with('(') && rhs.ends_with(')') && rhs.len()>=2 {
            let inside = &rhs[1..rhs.len()-1];
            let transformed_inside = transform_code_part(inside);
            return format!("{}({})", lhs, transformed_inside);
        } else {
            let transformed_rhs = transform_assignment_rhs(rhs);
            return format!("{}{}", lhs, transformed_rhs);
        }
    }
    word.to_string()
}

fn transform_assignment_rhs(rhs: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = rhs.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' && i+1 < chars.len() {
            let n = chars[i+1];
            if n == '(' {
                if i+2 < chars.len() && chars[i+2] == '(' {
                    let mut j = i+3;
                    let mut depth = 1;
                    while j < chars.len() {
                        if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                        if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                        j+=1;
                    }
                    let s: String = chars[i..j.min(chars.len())].iter().collect();
                    out.push_str(&s);
                    i = j; continue;
                } else {
                    let mut j = i+2;
                    let mut depth = 1;
                    let mut in_s=false; let mut in_d=false; let mut esc=false;
                    while j < chars.len() {
                        let ch = chars[j];
                        if esc { esc=false; j+=1; continue; }
                        if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                        if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                        if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                        if ch == '\'' { in_s=true; j+=1; continue; }
                        if ch == '"' { in_d=true; j+=1; continue; }
                        if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                        j+=1;
                    }
                    let inner = if j > i+2 { chars[i+2..j-1].iter().collect::<String>() } else { "".to_string() };
                    let transformed_inner = do_transform(&inner);
                    out.push_str(&format!("$({})", transformed_inner.trim()));
                    i = j; continue;
                }
            } else if n == '{' {
                if let Some(end) = find_matching_brace(&chars, i+1) {
                    let raw: String = chars[i..=end].iter().collect();
                    let inner = &raw[2..raw.len()-1];
                    if inner.starts_with('#') { out.push_str(&raw); }
                    else if inner.len()>=3 && inner.ends_with("[*]") {
                        let base = &inner[..inner.len()-3];
                        out.push_str(&format!("${{{}[@]}}", base));
                    } else if is_simple_identifier(inner) {
                        out.push_str(&format!("${}", inner));
                    } else { out.push_str(&raw); }
                    i = end+1; continue;
                }
            }
        }
        if c == '`' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' { j+=1; }
            if j < chars.len() { j+=1; }
            let inner = if j > i+1 { chars[i+1..j-1].iter().collect::<String>() } else { "".to_string() };
            let transformed_inner = do_transform(&inner);
            out.push('`'); out.push_str(transformed_inner.trim()); out.push('`');
            i = j; continue;
        }
        out.push(c); i+=1;
    }
    out
}

fn transform_word(word: &str, _in_assignment: bool) -> String {
    let mut result = String::new();
    let chars: Vec<char> = word.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg); i = j;
        } else if c == '"' {
            let mut j = i+1;
            let mut esc = false;
            let mut stack: Vec<String> = Vec::new();
            let mut in_s = false;
            let mut in_a = false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc = false; j+=1; continue; }
                if ch == '\\' && !in_s { esc = true; j+=1; continue; }
                if in_s { if ch == '\'' { in_s = false; } j+=1; continue; }
                if in_a { if ch == '\'' { in_a = false; } j+=1; continue; }
                if !stack.is_empty() {
                    if ch == '\'' { in_s = true; j+=1; continue; }
                    if ch == '"' { j+=1; continue; }
                    if ch == '$' && j+1 < chars.len() {
                        let n = chars[j+1];
                        if n == '(' {
                            if j+2 < chars.len() && chars[j+2] == '(' { stack.push("((".to_string()); j+=3; continue; }
                            else { stack.push("$(".to_string()); j+=2; continue; }
                        } else if n == '{' { stack.push("${".to_string()); j+=2; continue; }
                    }
                    if ch == ')' {
                        if stack.last().map_or(false, |s| s == "$(") { stack.pop(); j+=1; continue; }
                        else if stack.last().map_or(false, |s| s == "((") {
                            if j+1 < chars.len() && chars[j+1] == ')' { stack.pop(); j+=2; continue; }
                        }
                    }
                    if ch == '}' {
                        if stack.last().map_or(false, |s| s == "${") { stack.pop(); j+=1; continue; }
                    }
                    j+=1; continue;
                }
                if ch == '\'' {
                    if j>0 && chars[j-1] == '$' { in_a = true; } else { in_s = true; }
                    j+=1; continue;
                }
                if ch == '$' && j+1 < chars.len() {
                    let n = chars[j+1];
                    if n == '(' {
                        if j+2 < chars.len() && chars[j+2] == '(' { stack.push("((".to_string()); j+=3; continue; }
                        else { stack.push("$(".to_string()); j+=2; continue; }
                    } else if n == '{' { stack.push("${".to_string()); j+=2; continue; }
                }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            let inner = if seg.len()>=2 { &seg[1..seg.len()-1] } else { "" };
            let transformed_inner = transform_double_quoted_inner_complex(inner);
            result.push('"'); result.push_str(&transformed_inner); result.push('"');
            i = j;
        } else if c == '$' && i+1 < chars.len() && chars[i+1] == '\'' {
            let mut j = i+2;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg); i = j;
        } else if c == '$' && i+1 < chars.len() && chars[i+1] == '"' {
            let mut j = i+2;
            let mut esc = false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc = false; j+=1; continue; }
                if ch == '\\' { esc = true; j+=1; continue; }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg); i = j;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '\'' && chars[j] != '"' {
                if chars[j] == '$' && j+1 < chars.len() && (chars[j+1] == '\'' || chars[j+1] == '"') { break; }
                j+=1;
            }
            let seg: String = chars[i..j].iter().collect();
            result.push_str(&transform_unquoted_segment(&seg));
            i = j;
        }
    }
    result
}

fn transform_double_quoted_inner(inner: &str) -> String {
    let trimmed = inner.trim();
    if trimmed.starts_with("${") && trimmed.ends_with('}') {
        let inside = &trimmed[2..trimmed.len()-1];
        if is_simple_identifier(inside) {
            return format!("${}", inside);
        }
    }
    inner.to_string()
}

fn transform_double_quoted_inner_complex(inner: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = inner.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' && i+1 < chars.len() && chars[i+1] == '(' {
            if i+2 < chars.len() && chars[i+2] == '(' {
                let mut j = i+3;
                let mut depth = 1;
                while j < chars.len() {
                    if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                    if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                    j+=1;
                }
                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str(&s);
                i = j; continue;
            } else {
                let mut j = i+2;
                let mut depth = 1;
                let mut in_s=false; let mut in_d=false; let mut esc=false;
                while j < chars.len() {
                    let ch = chars[j];
                    if esc { esc=false; j+=1; continue; }
                    if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                    if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                    if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                    if ch == '\'' { in_s=true; j+=1; continue; }
                    if ch == '"' { in_d=true; j+=1; continue; }
                    if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                    j+=1;
                }
                let inner_cmd = if j > i+2 { chars[i+2..j-1].iter().collect::<String>() } else { "".to_string() };
                let transformed_inner = do_transform(&inner_cmd);
                out.push_str(&format!("$({})", transformed_inner.trim()));
                i = j; continue;
            }
        }
        if c == '$' && i+1 < chars.len() && chars[i+1] == '{' {
            if let Some(end) = find_matching_brace(&chars, i+1) {
                let raw: String = chars[i..=end].iter().collect();
                let inner_braced = &raw[2..raw.len()-1];
                if is_simple_identifier(inner_braced) {
                    out.push_str(&format!("${}", inner_braced));
                } else {
                    out.push_str(&raw);
                }
                i = end+1; continue;
            }
        }
        out.push(c); i+=1;
    }
    let trimmed = out.trim();
    if trimmed.starts_with("${") && trimmed.ends_with('}') && trimmed.matches("${").count()==1 {
        let inside = &trimmed[2..trimmed.len()-1];
        if is_simple_identifier(inside) {
            return format!("${}", inside);
        }
    }
    out
}

fn transform_unquoted_segment(seg: &str) -> String {
    #[derive(Debug)]
    enum SegToken { Var(String), Lit(String) }
    let mut tokens: Vec<SegToken> = Vec::new();
    let chars: Vec<char> = seg.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' {
            if i+1 >= chars.len() { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            let next = chars[i+1];
            if next == '{' {
                if let Some(end) = find_matching_brace(&chars, i+1) {
                    let var_text: String = chars[i..=end].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = end+1; continue;
                } else { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            } else if next == '(' {
                if i+2 < chars.len() && chars[i+2] == '(' {
                    let mut j = i+3; let mut depth = 1;
                    while j < chars.len() {
                        if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                        if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Lit(var_text)); i = j; continue;
                } else {
                    let mut j = i+2; let mut depth = 1; let mut in_s=false; let mut in_d=false; let mut esc=false;
                    while j < chars.len() {
                        let ch = chars[j];
                        if esc { esc=false; j+=1; continue; }
                        if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                        if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                        if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                        if ch == '\'' { in_s=true; j+=1; continue; }
                        if ch == '"' { in_d=true; j+=1; continue; }
                        if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = j; continue;
                }
            } else if "*@#?$!".contains(next) || next.is_ascii_digit() {
                let var_text = format!("${}", next);
                tokens.push(SegToken::Var(var_text)); i+=2; continue;
            } else if is_identifier_start(next) {
                let mut j = i+1;
                while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
                let var_text: String = chars[i..j].iter().collect();
                tokens.push(SegToken::Var(var_text)); i = j; continue;
            } else {
                tokens.push(SegToken::Lit("$".to_string())); i+=1; continue;
            }
        } else if c == '`' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' { j+=1; }
            if j < chars.len() { j+=1; }
            let var_text: String = chars[i..j.min(chars.len())].iter().collect();
            tokens.push(SegToken::Var(var_text)); i = j; continue;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '$' && chars[j] != '`' { j+=1; }
            let lit: String = chars[i..j].iter().collect();
            tokens.push(SegToken::Lit(lit)); i = j;
        }
    }
    struct Transformed { original: String, replacement: String, needs_quotes: bool, is_var: bool, is_glob: bool, is_star: bool }
    let mut transformed_tokens: Vec<Transformed> = Vec::new();
    for tok in tokens {
        match tok {
            SegToken::Lit(lit) => {
                let is_glob = lit.contains('*') || lit.contains('?');
                transformed_tokens.push(Transformed { original: lit.clone(), replacement: lit.clone(), needs_quotes: false, is_var: false, is_glob, is_star: false });
            },
            SegToken::Var(raw) => {
                let (rep, needs_quotes, is_star) = transform_var_token_inner(&raw);
                transformed_tokens.push(Transformed { original: raw.clone(), replacement: rep, needs_quotes, is_var: true, is_glob: false, is_star });
            }
        }
    }
    for idx in 0..transformed_tokens.len() {
        if transformed_tokens[idx].is_var && transformed_tokens[idx].original.starts_with("${") {
            if idx+1 < transformed_tokens.len() {
                let next = &transformed_tokens[idx+1];
                if !next.is_var && !next.replacement.is_empty() {
                    let first_char = next.replacement.chars().next().unwrap();
                    if is_identifier_char(first_char) {
                        let orig = &transformed_tokens[idx].original;
                        if orig.starts_with("${") && orig.ends_with('}') {
                            let inner = &orig[2..orig.len()-1];
                            if is_simple_identifier(inner) {
                                transformed_tokens[idx].replacement = format!("${{{}}}", inner);
                            }
                        }
                    }
                }
            }
        }
    }
    let mut output = String::new();
    let mut idx = 0;
    while idx < transformed_tokens.len() {
        let tok = &transformed_tokens[idx];
        if !tok.is_var || !tok.needs_quotes {
            output.push_str(&tok.replacement);
            idx+=1; continue;
        }
        let mut group_vars: Vec<String> = Vec::new();
        let mut group_lits: Vec<String> = Vec::new();
        let group_is_star_start = tok.is_star;
        group_vars.push(tok.replacement.clone());
        let mut j = idx+1;
        while j < transformed_tokens.len() {
            let lit_tok = &transformed_tokens[j];
            if !lit_tok.is_var {
                if lit_tok.is_glob { break; }
                if j+1 < transformed_tokens.len() {
                    let next_var = &transformed_tokens[j+1];
                    if next_var.is_var && next_var.needs_quotes {
                        group_lits.push(lit_tok.replacement.clone());
                        group_vars.push(next_var.replacement.clone());
                        j+=2; continue;
                    } else { break; }
                } else { break; }
            } else {
                if !lit_tok.needs_quotes { break; }
                if group_is_star_start { break; }
                group_lits.push("".to_string());
                group_vars.push(lit_tok.replacement.clone());
                j+=1; continue;
            }
        }
        let mut inner = String::new();
        for k in 0..group_vars.len() {
            inner.push_str(&group_vars[k]);
            if k < group_lits.len() { inner.push_str(&group_lits[k]); }
        }
        output.push('"'); output.push_str(&inner); output.push('"');
        idx = j;
    }
    output
}

fn transform_var_token_inner(raw: &str) -> (String, bool, bool) {
    if raw.starts_with("${") && raw.ends_with('}') {
        let inner = &raw[2..raw.len()-1];
        if inner.starts_with('#') { return (raw.to_string(), false, false); }
        if inner.len()>=3 && inner.ends_with("[@]") { return (raw.to_string(), true, false); }
        if inner.len()>=3 && inner.ends_with("[*]") {
            let base = &inner[..inner.len()-3];
            let final_raw = format!("${{{}[@]}}", base);
            return (final_raw, true, false);
        }
        if is_simple_identifier(inner) {
            return (format!("${}", inner), true, false);
        }
        return (raw.to_string(), true, false);
    }
    if raw.starts_with("$((") { return (raw.to_string(), false, false); }
    if raw.starts_with("$(") && raw.ends_with(')') {
        let inner = &raw[2..raw.len()-1];
        let transformed_inner = do_transform(inner);
        let new_raw = format!("$({})", transformed_inner.trim());
        return (new_raw, true, false);
    }
    if raw.starts_with('`') && raw.ends_with('`') && raw.len()>=2 {
        let inner = &raw[1..raw.len()-1];
        let transformed_inner = do_transform(inner);
        let new_raw = format!("$({})", transformed_inner.trim());
        return (new_raw, true, false);
    }
    if raw.len() == 2 {
        let ch = raw.chars().nth(1).unwrap();
        match ch {
            '*' => { return ("$@".to_string(), true, true); },
            '@' => { return ("$@".to_string(), true, false); },
            '#' | '?' | '!' | '$' => { return (raw.to_string(), false, false); },
            _ => {}
        }
    }
    if raw.len() == 2 && raw.chars().nth(1).unwrap().is_ascii_digit() {
        return (raw.to_string(), true, false);
    }
    if raw.starts_with('$') {
        let rest = &raw[1..];
        if !rest.is_empty() && is_identifier_start(rest.chars().next().unwrap()) {
            return (raw.to_string(), true, false);
        }
    }
    (raw.to_string(), true, false)
}

fn find_matching_brace(chars: &[char], open_pos: usize) -> Option<usize> {
    let mut depth = 0;
    for (idx, &c) in chars.iter().enumerate().skip(open_pos) {
        if c == '{' { depth+=1; }
        else if c == '}' {
            depth-=1;
            if depth==0 { return Some(idx); }
        }
    }
    None
}

fn suggest_diff(original: &str, _transformed: &str) -> String {
    let mut out = String::new();
    for line in original.lines() {
        let colored = transform_line_suggest(line);
        out.push_str(&colored);
        out.push('\n');
    }
    out
}

fn transform_line_suggest(line: &str) -> String {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut comment_start: Option<usize> = None;
    for (idx, c) in line.chars().enumerate() {
        if escaped { escaped = false; continue; }
        if c == '\\' && !in_single { escaped = true; continue; }
        if in_single { if c == '\'' { in_single = false; } continue; }
        if in_double { if c == '"' { in_double = false; } continue; }
        if c == '\'' { in_single = true; continue; }
        if c == '"' { in_double = true; continue; }
        if c == '#' {
            if idx==0 { comment_start = Some(idx); break; }
            else {
                let prev = line.chars().nth(idx-1).unwrap_or(' ');
                if prev.is_whitespace() || prev == ';' || prev == '&' || prev == '|' || prev == '(' {
                    comment_start = Some(idx); break;
                }
            }
        }
    }
    let (code_part, comment_part) = if let Some(cs) = comment_start {
        (&line[..cs], &line[cs..])
    } else { (line, "") };
    let transformed_code = transform_code_part_suggest(code_part);
    format!("{}{}", transformed_code, comment_part)
}

fn transform_code_part_suggest(code: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    let mut at_command_start = true;
    let mut seen_assignment = false;
    let mut after_export_local = false;
    let mut in_single = false;
    let mut in_double = false;
    let mut in_ansi = false;
    let mut escaped = false;
    let mut in_double_bracket = false;
    let mut case_next_no_quote = false;
    while i < chars.len() {
        let c = chars[i];
        if escaped { out.push(c); escaped = false; i+=1; continue; }
        if c == '\\' && !in_single { out.push(c); escaped = true; i+=1; continue; }
        if in_single { out.push(c); if c == '\'' { in_single = false; } i+=1; continue; }
        if in_ansi { out.push(c); if c == '\'' { in_ansi = false; } i+=1; continue; }
        if in_double {
            if c == '"' { out.push(c); in_double = false; i+=1; continue; }
            out.push(c); i+=1; continue;
        }
        if c == '\'' {
            if i>0 && chars[i-1] == '$' { out.push(c); in_ansi = true; }
            else { out.push(c); in_single = true; }
            i+=1; continue;
        }
        if c == '"' { out.push(c); in_double = true; i+=1; continue; }
        if c == ';' || c == '&' || c == '|' || c == '(' || c == ')' {
            out.push(c); at_command_start = true; seen_assignment = false; after_export_local = false;
            if c == '[' && i+1 < chars.len() && chars[i+1] == '[' { out.push(chars[i+1]); i+=2; in_double_bracket = true; continue; }
            if c == ']' && i+1 < chars.len() && chars[i+1] == ']' { out.push(chars[i+1]); i+=2; in_double_bracket = false; continue; }
            i+=1;
            if i < chars.len() {
                let nc = chars[i];
                if (c == '&' && nc == '&') || (c == '|' && nc == '|') { out.push(nc); i+=1; }
                else if c == '[' && nc == '[' { out.push(nc); i+=1; in_double_bracket = true; }
                else if c == ']' && nc == ']' { out.push(nc); i+=1; in_double_bracket = false; }
            }
            continue;
        }
        if c.is_whitespace() { out.push(c); i+=1; continue; }
        let mut j = i;
        let mut w_in_single = false;
        let mut w_in_double = false;
        let mut w_in_ansi = false;
        let mut w_esc = false;
        let mut w_in_backtick = false;
        let mut w_stack: Vec<String> = Vec::new();
        while j < chars.len() {
            let ch = chars[j];
            if w_esc { w_esc = false; j+=1; continue; }
            if ch == '\\' && !w_in_single { w_esc = true; j+=1; continue; }
            if w_in_single { if ch == '\'' { w_in_single = false; } j+=1; continue; }
            if w_in_ansi { if ch == '\'' { w_in_ansi = false; } j+=1; continue; }
            if w_in_double { if ch == '"' { w_in_double = false; } j+=1; continue; }
            if w_in_backtick { if ch == '`' { w_in_backtick = false; } j+=1; continue; }
            if !w_stack.is_empty() {
                if ch == '\'' { w_in_single = true; j+=1; continue; }
                if ch == '"' { w_in_double = true; j+=1; continue; }
                if ch == '`' { w_in_backtick = true; j+=1; continue; }
                if ch == '$' && j+1 < chars.len() {
                    let n = chars[j+1];
                    if n == '(' {
                        if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                        else { w_stack.push("$(".to_string()); j+=2; continue; }
                    } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
                }
                if ch == ')' {
                    if w_stack.last().map_or(false, |s| s == "$(") { w_stack.pop(); j+=1; continue; }
                    else if w_stack.last().map_or(false, |s| s == "((") {
                        if j+1 < chars.len() && chars[j+1] == ')' { w_stack.pop(); j+=2; continue; }
                    }
                }
                if ch == '}' {
                    if w_stack.last().map_or(false, |s| s == "${") { w_stack.pop(); j+=1; continue; }
                }
                j+=1; continue;
            }
            if ch == '\'' {
                if j>0 && chars[j-1] == '$' { w_in_ansi = true; } else { w_in_single = true; }
                j+=1; continue;
            }
            if ch == '"' { w_in_double = true; j+=1; continue; }
            if ch == '`' { w_in_backtick = true; j+=1; continue; }
            if ch == '$' && j+1 < chars.len() {
                let n = chars[j+1];
                if n == '(' {
                    if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                    else { w_stack.push("$(".to_string()); j+=2; continue; }
                } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
            }
            if ch.is_whitespace() || ch == ';' || ch == '&' || ch == '|' || ch == '(' || ch == ')' || ch == '<' || ch == '>' { break; }
            j+=1;
        }
        let word: String = chars[i..j].iter().collect();
        if word == "case" {
            case_next_no_quote = true;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if word == "[[" {
            in_double_bracket = true;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if word == "]]" {
            in_double_bracket = false;
            out.push_str(&word);
            i = j;
            at_command_start = true;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if case_next_no_quote {
            case_next_no_quote = false;
            out.push_str(&word);
            i = j;
            at_command_start = false;
            seen_assignment = false;
            after_export_local = false;
            continue;
        }
        if in_double_bracket {
            out.push_str(&word);
            i = j;
            if word.contains("]]") { in_double_bracket = false; at_command_start = true; }
            continue;
        }
        let is_assignment = is_assignment_word(&word, at_command_start, seen_assignment, after_export_local);
        let is_introducer = is_assignment_introducer_word(&word);
        let transformed_word = if is_assignment { transform_assignment_word(&word) }
        else if is_introducer { after_export_local = true; word.clone() }
        else { transform_word_suggest(&word) };
        if is_assignment { seen_assignment = true; }
        else if is_introducer { at_command_start = true; seen_assignment = false; }
        else { at_command_start = false; seen_assignment = false; after_export_local = false; }
        out.push_str(&transformed_word);
        i = j;
    }
    out
}
fn transform_word_suggest(word: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = word.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg); i = j;
        } else if c == '"' {
            let mut j = i+1;
            let mut esc = false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc = false; j+=1; continue; }
                if ch == '\\' { esc = true; j+=1; continue; }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg);
            i = j;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '\'' && chars[j] != '"' { j+=1; }
            let seg: String = chars[i..j].iter().collect();
            result.push_str(&transform_unquoted_segment_suggest(&seg));
            i = j;
        }
    }
    result
}
fn transform_unquoted_segment_suggest(seg: &str) -> String {
    #[derive(Debug)]
    enum SegToken { Var(String), Lit(String) }
    let mut tokens: Vec<SegToken> = Vec::new();
    let chars: Vec<char> = seg.chars().collect();
    let mut i = 0;
