                output.push_str(&format!("${{{}[", base));
                if k == group_vars.len()-1 {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\"\x1b[m");
                    output.push_str("]}");
                } else {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\x1b[m");
                    output.push_str("]}");
                }
            } else if gv.is_star {
                output.push('$');
                if k == group_vars.len()-1 {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\"\x1b[m");
                } else {
                    output.push_str("\x1b[0;41m*\x1b[0;42m@\x1b[m");
                }
            } else {
                output.push_str(&gv.replacement);
            }
            if k < group_lits.len() && !has_star {
                output.push_str(&group_lits[k]);
            }
        }
        if !has_star && !group_vars.iter().any(|gv| gv.is_braced && gv.original.starts_with("${")) && !group_vars.iter().any(|gv| gv.original.contains("[*]")) {
            output.push_str("\x1b[0;42m\"\x1b[m");
        }
        idx = j;
    }
    output
}

fn syntax_highlight(content: &str) -> Result<String, String> {
    let mut out = String::new();
    let chars: Vec<char> = content.chars().collect();
    let mut i = 0;
    let mut at_line_start = true;
    while i < chars.len() {
        let c = chars[i];
        if c == '\n' { out.push('\n'); at_line_start = true; i+=1; continue; }
        if at_line_start && c == '#' {
            let mut j = i;
            while j < chars.len() && chars[j] != '\n' { j+=1; }
            let comment: String = chars[i..j].iter().collect();
            out.push_str("\x1b[0;1;3;38;2;120;144;96m");
            out.push_str(&comment);
            out.push_str("\x1b[m");
            i = j; continue;
        }
        if c.is_whitespace() { out.push(c); i+=1; continue; }
        if c == '\'' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let s: String = chars[i..j.min(chars.len())].iter().collect();
            out.push_str("\x1b[0;38;2;255;204;85m");
            out.push_str(&s);
            out.push_str("\x1b[m");
            i = j; at_line_start = false; continue;
        }
        if c == '$' && i+1 < chars.len() && chars[i+1] == '\'' {
            let mut j = i+2;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let s: String = chars[i..j.min(chars.len())].iter().collect();
            out.push_str("\x1b[0;38;2;255;128;0m");
            out.push_str(&s);
            out.push_str("\x1b[m");
            i = j; at_line_start = false; continue;
        }
        if c == '"' {
            let mut j = i+1;
            let mut esc = false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc=false; j+=1; continue; }
                if ch == '\\' { esc=true; j+=1; continue; }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let full: String = chars[i..j.min(chars.len())].iter().collect();
            let inner = if full.len()>=2 { &full[1..full.len()-1] } else { "" };
            out.push_str("\x1b[0;38;2;255;0;0m\"");
            let inner_chars: Vec<char> = inner.chars().collect();
            let mut k = 0;
            while k < inner_chars.len() {
                let ch = inner_chars[k];
                if ch == '\\' && k+1 < inner_chars.len() {
                    let next = inner_chars[k+1];
                    if next == '$' || next == '"' || next == '\\' {
                        out.push_str("\x1b[0;1;38;2;255;0;128m");
                        out.push('\\'); out.push(next);
                        out.push_str("\x1b[0;38;2;255;0;0m");
                        k+=2; continue;
                    }
                }
                if ch == '$' {
                    if k+1 < inner_chars.len() {
                        let next = inner_chars[k+1];
                        if next == '{' {
                            if let Some(end) = inner[k..].find('}') {
                                let var = &inner[k..k+end+1];
                                out.push_str("\x1b[0;38;2;63;127;207m");
                                out.push_str(var);
                                out.push_str("\x1b[0;38;2;255;0;0m");
                                k+=end+1; continue;
                            }
                        } else if "*@#?$!0123456789".contains(next) || is_identifier_start(next) {
                            let mut var_end = k+1;
                            if is_identifier_start(next) {
                                var_end+=1;
                                while var_end < inner_chars.len() && is_identifier_char(inner_chars[var_end]) { var_end+=1; }
                            } else { var_end+=1; }
                            let var = &inner[k..var_end];
                            out.push_str("\x1b[0;38;2;63;127;207m");
                            out.push_str(var);
                            out.push_str("\x1b[0;38;2;255;0;0m");
                            k = var_end; continue;
                        }
                    }
                }
                out.push(ch); k+=1;
            }
            out.push_str("\"\x1b[m");
            i = j; at_line_start = false; continue;
        }
        if c == '$' {
            let mut j = i;
            let mut w_in_single = false;
            let mut w_in_double = false;
            let mut w_esc = false;
            while j < chars.len() {
                let ch = chars[j];
                if w_esc { w_esc=false; j+=1; continue; }
                if ch == '\\' && !w_in_single { w_esc=true; j+=1; continue; }
                if w_in_single { if ch == '\'' { w_in_single=false; } j+=1; continue; }
                if w_in_double { if ch == '"' { w_in_double=false; } j+=1; continue; }
                if ch == '\'' { w_in_single=true; j+=1; continue; }
                if ch == '"' { w_in_double=true; j+=1; continue; }
                if ch.is_whitespace() || ch == ';' || ch == '&' || ch == '|' { break; }
                j+=1;
            }
            let word = chars[i..j].iter().collect::<String>();
            let colored_word = highlight_word_with_grouping(&word);
            out.push_str(&colored_word);
            i = j;
            at_line_start = false;
            continue;
        }
        if c.is_alphabetic() && at_line_start {
            let mut j = i;
            while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_' || chars[j] == '-') { j+=1; }
            let w: String = chars[i..j].iter().collect();
            if matches!(w.as_str(), "if" | "then" | "else" | "elif" | "fi" | "for" | "in" | "do" | "done" | "case" | "esac" | "while" | "until" | "function" | "select" | "time" | "local" | "export" | "declare") {
                out.push_str("\x1b[0;1m"); out.push_str(&w); out.push_str("\x1b[m");
            } else {
                out.push_str("\x1b[0;38;2;192;0;128m"); out.push_str(&w); out.push_str("\x1b[m");
            }
            i = j; at_line_start = false; continue;
        }
        out.push(c);
        if !c.is_whitespace() { at_line_start = false; }
        i+=1;
    }
    Ok(out)
}

fn highlight_word_with_grouping(word: &str) -> String {
    #[derive(Debug)]
    enum Tok { Var(String), Lit(String) }
    let chars: Vec<char> = word.chars().collect();
    let mut tokens: Vec<Tok> = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' {
            if i+1 >= chars.len() { tokens.push(Tok::Lit("$".to_string())); i+=1; continue; }
            let next = chars[i+1];
            if next == '{' {
                if let Some(end) = find_matching_brace(&chars, i+1) {
                    let var_text: String = chars[i..=end].iter().collect();
                    tokens.push(Tok::Var(var_text)); i = end+1; continue;
                } else { tokens.push(Tok::Lit("$".to_string())); i+=1; continue; }
            } else if "*@#?$!".contains(next) || next.is_ascii_digit() {
                tokens.push(Tok::Var(format!("${}", next))); i+=2; continue;
            } else if is_identifier_start(next) {
                let mut j = i+1;
                while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
                tokens.push(Tok::Var(chars[i..j].iter().collect())); i = j; continue;
            } else {
                tokens.push(Tok::Lit("$".to_string())); i+=1; continue;
            }
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '$' { j+=1; }
            tokens.push(Tok::Lit(chars[i..j].iter().collect())); i = j;
        }
    }
    let mut out = String::new();
    let mut idx = 0;
    while idx < tokens.len() {
        match &tokens[idx] {
            Tok::Lit(lit) => { out.push_str(lit); idx+=1; },
            Tok::Var(var) => {
                let mut group_vars: Vec<String> = vec![var.clone()];
                let mut group_lits: Vec<String> = Vec::new();
                let mut j = idx+1;
                while j < tokens.len() {
                    match &tokens[j] {
                        Tok::Lit(lit) => {
                            if lit.contains('*') || lit.contains('?') { break; }
                            if j+1 < tokens.len() {
                                if let Tok::Var(next_var) = &tokens[j+1] {
                                    group_lits.push(lit.clone());
                                    group_vars.push(next_var.clone());
                                    j+=2; continue;
                                } else { break; }
                            } else { break; }
                        },
                        Tok::Var(next_var) => {
                            group_lits.push("".to_string());
                            group_vars.push(next_var.clone());
                            j+=1; continue;
                        }
                    }
                }
                if group_vars.len() > 1 {
                    for k in 0..group_vars.len() {
                        if k==0 {
                            out.push_str("\x1b[0;38;2;63;127;207m");
                            out.push_str(&group_vars[k]);
                        } else {
                            out.push_str("\x1b[0;38;2;63;127;207m");
                            out.push_str(&group_vars[k]);
                        }
                        if k < group_lits.len() {
                            let lit = &group_lits[k];
                            if !lit.is_empty() {
                                out.push_str("\x1b[0;38;2;255;0;0m");
                                out.push_str(lit);
                            }
                        }
                    }
                    out.push_str("\x1b[m");
                } else {
                    out.push_str("\x1b[0;38;2;63;127;207m");
                    out.push_str(&group_vars[0]);
                    out.push_str("\x1b[m");
                }
                idx = j;
            }
        }
    }
    out
}

fn syntax_highlight_with_suggest(content: &str, transformed: &str) -> Result<String, String> {
    if content == transformed {
        return syntax_highlight(content);
    }
    let highlighted = syntax_highlight(transformed)?;
    Ok(highlighted)
}

fn do_transform_with_pitfall(content: &str) -> String {
    let mut out = String::new();
    for line in content.split_inclusive('\n') {
        let has_nl = line.ends_with('\n');
        let line_content = if has_nl { &line[..line.len()-1] } else { line };
        let bytes = line_content.as_bytes();
        let mut i = 0;
        let mut found = None;
        while i+2 < bytes.len() {
            if bytes[i] == b'$' && (bytes[i+1] as char).is_ascii_digit() && (bytes[i+2] as char).is_ascii_digit() {
                found = Some(i);
                break;
            }
            i+=1;
        }
        if let Some(pos) = found {
            let before = &line_content[..pos];
            out.push_str(&transform_line(before));
            if has_nl { out.push('\n'); }
        } else {
            out.push_str(&transform_line(line_content));
            if has_nl { out.push('\n'); }
        }
    }
    out
}
