                output.push_str("\\x1b[0;42m\"\\x1b[m");
            }
        } else if group_vars.iter().any(|gv| gv.original.contains("[*]")) {
            // array star already handled? Need final?
            // For [*] we already pushed final in loop? We push @\" + ]} then final? Actually we push @\" + ]} + final? Let's just ensure final push if not star
            // For [*] we pushed final already? In our code for [*] last we push "]}"? Wait we push "]}"? Let's push final green "
            if !has_star {
                output.push_str("\\x1b[0;42m\"\\x1b[m");
            }
        }
        // For star case, closing already included, skip
"""

