                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str("\x1b[0;38;2;255;204;85m");
                out.push_str(&s);
                out.push_str("\x1b[m");
                i = j;
                in_single = false;
                continue;
            }
            out.push(c); i+=1; continue;
        }
        if in_ansi {
            if c == '\'' {
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                // Actually ansi-c already handled, but for simplicity
                out.push(c); i+=1; continue;
            }
            out.push(c); i+=1; continue;
        }
        if in_double {
            if c == '"' { out.push_str("\x1b[0;38;2;255;0;0m\"\x1b[m"); in_double = false; i+=1; continue; }
            out.push(c); i+=1; continue;
        }
        if c == '\'' {
            if i>0 && chars[i-1] == '$' { in_ansi = true; out.push(c); }
            else { in_single = true; out.push_str("\x1b[0;38;2;255;204;85m'"); }
            i+=1; continue;
        }
        if c == '"' { out.push_str("\x1b[0;38;2;255;0;0m\""); in_double = true; i+=1; continue; }
        if c == ';' || c == '&' || c == '|' || c == '(' || c == ')' {
            out.push(c); at_command_start = true; seen_assignment = false; after_export_local = false;
            i+=1;
            continue;
        }
        if c.is_whitespace() { out.push(c); i+=1; continue; }

        // Collect word
        let mut j = i;
        let mut w_in_single = false;
        let mut w_in_double = false;
        let mut w_in_ansi = false;
        let mut w_esc = false;
        let mut w_in_backtick = false;
        let mut w_stack: Vec<String> = Vec::new();
        while j < chars.len() {
            let ch = chars[j];
            if w_esc { w_esc = false; j+=1; continue; }
            if ch == '\\' && !w_in_single { w_esc = true; j+=1; continue; }
            if w_in_single { if ch == '\'' { w_in_single = false; } j+=1; continue; }
            if w_in_ansi { if ch == '\'' { w_in_ansi = false; } j+=1; continue; }
            if w_in_double { if ch == '"' { w_in_double = false; } j+=1; continue; }
            if w_in_backtick { if ch == '`' { w_in_backtick = false; } j+=1; continue; }
            if !w_stack.is_empty() {
                if ch == '\'' { w_in_single = true; j+=1; continue; }
                if ch == '"' { w_in_double = true; j+=1; continue; }
                if ch == '`' { w_in_backtick = true; j+=1; continue; }
                if ch == '$' && j+1 < chars.len() {
                    let n = chars[j+1];
                    if n == '(' {
                        if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                        else { w_stack.push("$(".to_string()); j+=2; continue; }
                    } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
                }
                if ch == ')' {
                    if w_stack.last().map_or(false, |s| s == "$(") { w_stack.pop(); j+=1; continue; }
                    else if w_stack.last().map_or(false, |s| s == "((") {
                        if j+1 < chars.len() && chars[j+1] == ')' { w_stack.pop(); j+=2; continue; }
                    }
                }
                if ch == '}' {
                    if w_stack.last().map_or(false, |s| s == "${") { w_stack.pop(); j+=1; continue; }
                }
                j+=1; continue;
            }
            if ch == '\'' {
                if j>0 && chars[j-1] == '$' { w_in_ansi = true; } else { w_in_single = true; }
                j+=1; continue;
            }
            if ch == '"' { w_in_double = true; j+=1; continue; }
            if ch == '`' { w_in_backtick = true; j+=1; continue; }
            if ch == '$' && j+1 < chars.len() {
                let n = chars[j+1];
                if n == '(' {
                    if j+2 < chars.len() && chars[j+2] == '(' { w_stack.push("((".to_string()); j+=3; continue; }
                    else { w_stack.push("$(".to_string()); j+=2; continue; }
                } else if n == '{' { w_stack.push("${".to_string()); j+=2; continue; }
            }
            if ch.is_whitespace() || ch == ';' || ch == '&' || ch == '|' || ch == '(' || ch == ')' || ch == '<' || ch == '>' { break; }
            j+=1;
        }
        let word: String = chars[i..j].iter().collect();
        // Check for keywords that should be bold and reset command start
        if word == "if" || word == "then" || word == "else" || word == "elif" || word == "fi" || word == "for" || word == "in" || word == "do" || word == "done" || word == "case" || word == "esac" || word == "while" || word == "until" || word == "function" || word == "select" {
            out.push_str("\x1b[0;1m");
            out.push_str(&word);
            out.push_str("\x1b[m");
            i=j;
            at_command_start = false;
            continue;
        }
        if word == "[[" || word == "]]" {
            // [[ and ]] are purple and indicate double bracket mode
            out.push_str("\x1b[0;38;2;192;0;192m");
            out.push_str(&word);
            out.push_str("\x1b[m");
            i=j;
            continue;
        }
        // For normal words, produce suggest with syntax colors
        let colored = transform_word_syntax_suggest(&word);
        out.push_str(&colored);
        i=j;
        if !word.contains('=') {
            at_command_start = false;
        }
    }
    out
}

fn transform_word_syntax_suggest(word: &str) -> String {
    // For default mode, we want syntax highlighting plus diff
    // We'll transform the word into quoted groups with green background and var colors

    // Parse word into unquoted and quoted segments, then for unquoted, produce colored groups with var blue and green quotes and red braces/* etc

    // For simplicity, we will handle unquoted segment only

    // We'll reuse transform_unquoted_segment_suggest but add var colors (blue)

    let mut result = String::new();
    let chars: Vec<char> = word.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str("\x1b[0;38;2;255;204;85m");
            result.push_str(&seg);
            result.push_str("\x1b[m");
            i=j;
        } else if c == '"' {
            // Already quoted, keep as is with syntax colors? For suggest mode, already quoted stays, but for syntax-suggest we need to keep red quotes?
            // For already quoted like "$VAR", it stays as is in transform, so syntax-suggest should show it as red " + var blue + red " (no green) if unchanged?
            // But if original was "$VAR" (already quoted) and transformed is same, then syntax-suggest should be same as syntax (red quotes)
            // So for already quoted words that are unchanged, we should not add green
            // For simplicity, we will output the word as is with syntax colors (red for quotes)
            let mut j = i+1;
            let mut esc=false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc=false; j+=1; continue; }
                if ch == '\\' { esc=true; j+=1; continue; }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            // Highlight seg as double-quoted string with var colors
            // We'll use syntax_highlight for this seg
            let inner = if seg.len()>=2 { &seg[1..seg.len()-1] } else { "" };
            result.push_str("\x1b[0;38;2;255;0;0m\"");
            result.push_str(inner);
            result.push_str("\"\x1b[m");
            i=j;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '\'' && chars[j] != '"' { j+=1; }
            let seg: String = chars[i..j].iter().collect();
            result.push_str(&transform_unquoted_segment_syntax_suggest(&seg));
            i=j;
        }
    }
    result
}

fn transform_unquoted_segment_syntax_suggest(seg: &str) -> String {
