fn transform_unquoted_segment_syntax_suggest(seg: &str) -> String {
    // Similar to suggest but with var colors (blue) for $VAR and green background for inserted quotes
    #[derive(Debug)]
    enum SegToken { Var(String), Lit(String) }
    let mut tokens: Vec<SegToken> = Vec::new();
    let chars: Vec<char> = seg.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' {
            if i+1 >= chars.len() { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            let next = chars[i+1];
            if next == '{' {
                if let Some(end) = find_matching_brace(&chars, i+1) {
                    let var_text: String = chars[i..=end].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = end+1; continue;
                } else { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            } else if next == '(' {
                if i+2 < chars.len() && chars[i+2] == '(' {
                    let mut j = i+3; let mut depth = 1;
                    while j < chars.len() {
                        if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                        if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Lit(var_text)); i = j; continue;
                } else {
                    let mut j = i+2; let mut depth = 1; let mut in_s=false; let mut in_d=false; let mut esc=false;
                    while j < chars.len() {
                        let ch = chars[j];
                        if esc { esc=false; j+=1; continue; }
                        if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                        if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                        if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                        if ch == '\'' { in_s=true; j+=1; continue; }
                        if ch == '"' { in_d=true; j+=1; continue; }
                        if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = j; continue;
                }
