    for tok in tokens {
        match tok {
            SegToken::Lit(lit) => {
                transformed_tokens.push(Transformed { original: lit.clone(), replacement: lit.clone(), needs_quotes: false, is_star: false, is_braced: false, brace_inner: "".to_string() });
