                output.push_str("\x1b[0;41m{\x1b[0;38;2;63;127;207m");
                output.push_str(&gv.brace_inner);
                output.push_str("\x1b[0;41m}\x1b[0;42m");
            } else if gv.is_star {
                output.push_str("\x1b[0;38;2;63;127;207m$\x1b[0;41m*\x1b[0;42m@");
            } else if gv.original.contains("[*]") {
