                output.push_str("\x1b[0;41m*\x1b[0;42m@");
                output.push_str("\x1b[0;38;2;63;127;207m]}");
            } else {
                output.push_str("\x1b[0;38;2;63;127;207m");
                output.push_str(&gv.replacement);
            }
        }
        output.push_str("\x1b[0;42m\"\x1b[m");
        idx = j;
    }
    output
}

