        else { transform_word_suggest(&word) };
        if is_assignment { seen_assignment = true; }
        else if is_introducer { at_command_start = true; seen_assignment = false; }
        else { at_command_start = false; seen_assignment = false; after_export_local = false; }
        out.push_str(&transformed_word);
        i = j;
    }
    out
}
fn transform_word_suggest(word: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = word.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '\'' { j+=1; }
            if j < chars.len() { j+=1; }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg); i = j;
        } else if c == '"' {
            let mut j = i+1;
            let mut esc = false;
            while j < chars.len() {
                let ch = chars[j];
                if esc { esc = false; j+=1; continue; }
                if ch == '\\' { esc = true; j+=1; continue; }
                if ch == '"' { j+=1; break; }
                j+=1;
            }
            let seg: String = chars[i..j.min(chars.len())].iter().collect();
            result.push_str(&seg);
            i = j;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '\'' && chars[j] != '"' { j+=1; }
            let seg: String = chars[i..j].iter().collect();
            result.push_str(&transform_unquoted_segment_suggest(&seg));
            i = j;
        }
    }
    result
}
fn transform_unquoted_segment_suggest(seg: &str) -> String {
    #[derive(Debug)]
    enum SegToken { Var(String), Lit(String) }
    let mut tokens: Vec<SegToken> = Vec::new();
    let chars: Vec<char> = seg.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '$' {
            if i+1 >= chars.len() { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            let next = chars[i+1];
            if next == '{' {
                if let Some(end) = find_matching_brace(&chars, i+1) {
                    let var_text: String = chars[i..=end].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = end+1; continue;
                } else { tokens.push(SegToken::Lit("$".to_string())); i+=1; continue; }
            } else if next == '(' {
                if i+2 < chars.len() && chars[i+2] == '(' {
                    let mut j = i+3; let mut depth = 1;
                    while j < chars.len() {
                        if j+1 < chars.len() && chars[j] == '(' && chars[j+1] == '(' { depth+=1; j+=2; continue; }
                        if j+1 < chars.len() && chars[j] == ')' && chars[j+1] == ')' { depth-=1; if depth==0 { j+=2; break; } j+=2; continue; }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Lit(var_text)); i = j; continue;
                } else {
                    let mut j = i+2; let mut depth = 1; let mut in_s=false; let mut in_d=false; let mut esc=false;
                    while j < chars.len() {
                        let ch = chars[j];
                        if esc { esc=false; j+=1; continue; }
                        if ch == '\\' && !in_s { esc=true; j+=1; continue; }
                        if in_s { if ch == '\'' { in_s=false; } j+=1; continue; }
                        if in_d { if ch == '"' { in_d=false; } j+=1; continue; }
                        if ch == '\'' { in_s=true; j+=1; continue; }
                        if ch == '"' { in_d=true; j+=1; continue; }
                        if ch == '(' { depth+=1; } else if ch == ')' { depth-=1; if depth==0 { j+=1; break; } }
                        j+=1;
                    }
                    let var_text: String = chars[i..j.min(chars.len())].iter().collect();
                    tokens.push(SegToken::Var(var_text)); i = j; continue;
                }
            } else if "*@#?$!".contains(next) || next.is_ascii_digit() {
                let var_text = format!("${}", next);
                tokens.push(SegToken::Var(var_text)); i+=2; continue;
            } else if is_identifier_start(next) {
                let mut j = i+1;
                while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
                let var_text: String = chars[i..j].iter().collect();
                tokens.push(SegToken::Var(var_text)); i = j; continue;
            } else {
                tokens.push(SegToken::Lit("$".to_string())); i+=1; continue;
            }
        } else if c == '`' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' { j+=1; }
            if j < chars.len() { j+=1; }
            let var_text: String = chars[i..j.min(chars.len())].iter().collect();
            tokens.push(SegToken::Var(var_text)); i = j; continue;
        } else {
            let mut j = i;
            while j < chars.len() && chars[j] != '$' && chars[j] != '`' { j+=1; }
            let lit: String = chars[i..j].iter().collect();
            tokens.push(SegToken::Lit(lit)); i = j;
        }
    }
    struct Transformed { original: String, replacement: String, needs_quotes: bool, is_var: bool, is_glob: bool, is_star: bool, is_braced: bool, brace_inner: String }
    let mut transformed_tokens: Vec<Transformed> = Vec::new();
    for tok in tokens {
        match tok {
            SegToken::Lit(lit) => {
                let is_glob = lit.contains('*') || lit.contains('?');
                transformed_tokens.push(Transformed { original: lit.clone(), replacement: lit.clone(), needs_quotes: false, is_var: false, is_glob, is_star: false, is_braced: false, brace_inner: "".to_string() });
            },
            SegToken::Var(raw) => {
                let (rep, needs_quotes, is_star) = transform_var_token_inner(&raw);
                let is_braced = raw.starts_with("${") && raw.ends_with('}');
                let brace_inner = if is_braced {
                    let inner = &raw[2..raw.len()-1];
                    if is_simple_identifier(inner) { inner.to_string() } else { "".to_string() }
                } else { "".to_string() };
                transformed_tokens.push(Transformed { original: raw.clone(), replacement: rep, needs_quotes, is_var: true, is_glob: false, is_star, is_braced, brace_inner });
            }
        }
    }
    for idx in 0..transformed_tokens.len() {
        if transformed_tokens[idx].is_var && transformed_tokens[idx].original.starts_with("${") {
            if idx+1 < transformed_tokens.len() {
                let next = &transformed_tokens[idx+1];
                if !next.is_var && !next.replacement.is_empty() {
                    let first_char = next.replacement.chars().next().unwrap();
                    if is_identifier_char(first_char) {
                        let orig = &transformed_tokens[idx].original;
                        if orig.starts_with("${") && orig.ends_with('}') {
                            let inner = &orig[2..orig.len()-1];
                            if is_simple_identifier(inner) {
                                transformed_tokens[idx].replacement = format!("${{{}}}", inner);
