fn syntax_highlight_with_suggest(original: &str, transformed: &str) -> Result<String, String> {
    if original == transformed {
        return syntax_highlight(original);
    }
    let mut out = String::new();
    for line in original.lines() {
        out.push_str(&transform_line_syntax_suggest(line));
        out.push('\n');
    }
    Ok(out)
}

fn transform_line_syntax_suggest(line: &str) -> String {
    // Handle comment
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut comment_start: Option<usize> = None;
    for (idx, c) in line.chars().enumerate() {
        if escaped { escaped = false; continue; }
        if c == '\\' && !in_single { escaped = true; continue; }
        if in_single { if c == '\'' { in_single = false; } continue; }
        if in_double { if c == '"' { in_double = false; } continue; }
        if c == '\'' { in_single = true; continue; }
        if c == '"' { in_double = true; continue; }
        if c == '#' {
            if idx==0 { comment_start = Some(idx); break; }
            else {
                let prev = line.chars().nth(idx-1).unwrap_or(' ');
                if prev.is_whitespace() || prev == ';' || prev == '&' || prev == '|' || prev == '(' {
                    comment_start = Some(idx); break;
                }
            }
        }
    }
    let (code_part, comment_part) = if let Some(cs) = comment_start {
        (&line[..cs], &line[cs..])
    } else { (line, "") };
    let transformed_code = transform_code_part_syntax_suggest(code_part);
    format!("{}{}", transformed_code, comment_part)
}

fn transform_code_part_syntax_suggest(code: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    let mut at_command_start = true;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() { out.push(c); i+=1; continue; }
        let mut j = i;
        while j < chars.len() && !chars[j].is_whitespace() { j+=1; }
        let word = chars[i..j].iter().collect::<String>();
        if matches!(word.as_str(), "if" | "then" | "else" | "elif" | "fi" | "for" | "in" | "do" | "done" | "case" | "esac" | "while" | "until" | "function" | "select" | "time" | "local" | "export" | "declare") {
            out.push_str("\x1b[0;1m"); out.push_str(&word); out.push_str("\x1b[m");
        } else if word == "[[" || word == "]]" {
            out.push_str("\x1b[0;38;2;192;0;192m"); out.push_str(&word); out.push_str("\x1b[m");
        } else if word.contains('$') {
            out.push_str(&transform_word_syntax_suggest(&word));
        } else {
            // Check if command at start
            if at_command_start {
                out.push_str("\x1b[0;38;2;192;0;128m"); out.push_str(&word); out.push_str("\x1b[m");
            } else {
                out.push_str(&word);
            }
        }
        if !word.is_empty() && (at_command_start || word == ";" || word == "&&" || word == "||") {
            at_command_start = true;
        } else if !word.contains('=') {
            at_command_start = false;
        }
        i=j;
    }
    out
}

fn transform_word_syntax_suggest(word: &str) -> String {
    // For default mode, produce with syntax colors plus green background for inserted quotes and red for braces/* etc
    // We'll handle $VAR, ${VAR}, $*, ${VAR[*]} etc

    // If word is exactly $VAR, output green quote + var color $VAR + green quote
    if let Some(var_name) = parse_simple_var(word) {
        if var_name == "*" {
            return "\x1b[0;42m\"\x1b[0;38;2;63;127;207m$\x1b[0;41m*\x1b[0;42m@\"\x1b[m".to_string();
        } else if var_name == "@" {
            return "\x1b[0;42m\"\x1b[0;38;2;63;127;207m$@\x1b[0;42m\"\x1b[m".to_string();
        } else {
            return format!("\x1b[0;42m\"\x1b[0;38;2;63;127;207m${}\x1b[0;42m\"\x1b[m", var_name);
        }
    }
    if word.starts_with("${") && word.ends_with('}') {
        let inner = &word[2..word.len()-1];
        if is_simple_identifier(inner) {
            return format!("\x1b[0;42m\"\x1b[0;38;2;63;127;207m$\x1b[0;41m{{\x1b[0;38;2;63;127;207m{}\x1b[0;41m}}\x1b[0;42m\"\x1b[m", inner);
        } else if inner.ends_with("[*]") {
            let base = inner.trim_end_matches("[*]");
            return format!("\x1b[0;42m\"\x1b[0;38;2;63;127;207m${{{}[\x1b[0;41m*\x1b[0;42m@\x1b[0;38;2;63;127;207m]}}\x1b[0;42m\"\x1b[m", base);
        } else if inner.ends_with("[@]") {
            return format!("\x1b[0;42m\"\x1b[0;38;2;63;127;207m{}\x1b[0;42m\"\x1b[m", word);
        }
    }
    // For $HOME/$VAR etc with grouping, we need to handle similar to syntax highlighting but with green quotes around group and red for literals between
    // For simplicity, if word contains / and $ then produce green quotes around whole grouped part plus red for / between vars
    if word.contains('/') && word.contains('$') {
