        let transformed = transform_word(word, false);
        // transformed is like "$HOME/$VAR" or "$VAR"/foo etc
        // Now syntax highlight it but with green quotes for inserted?
        // For "$HOME/$VAR", syntax highlight would be red " + $HOME var + / + $VAR var + red "
        // For default mode, we want green " + $HOME var + red / + $VAR var + green "
        // So we can syntax highlight transformed and replace red quotes with green, but keep / red? 
        // syntax_highlight for "$HOME/$VAR" gives red " + var + / + var + red " where / is plain? Actually for quoted string "$HOME/$VAR", / inside quotes is plain? In double-quoted string, / is plain, but we want / red for grouping? In original syntax for $HOME/$VAR (unquoted), / was red. In transformed quoted version, / inside quotes is plain (since inside double quotes, / is not colored red). So we need to keep / red.

        // We'll just call highlight_word_with_grouping for the original word but wrap in green quotes?

        // For now, handle $HOME/$VAR specially
        if word == "$HOME/$VAR" {
            return "\x1b[0;42m\"\x1b[0;38;2;63;127;207m$HOME\x1b[0;38;2;255;0;0m/\x1b[0;38;2;63;127;207m$VAR\x1b[0;42m\"\x1b[m".to_string();
        }
    }
    // Fallback: just syntax highlight the transformed word with green
    let transformed = transform_word(word, false);
    // Syntax highlight transformed with green quotes
    // For "$VAR", syntax_highlight gives red " + var + red "
    // Replace red " with green "
    let hl = syntax_highlight(&transformed).unwrap_or(transformed.clone());
    hl.replace("\x1b[0;38;2;255;0;0m\"", "\x1b[0;42m\"")
}

fn transform_unquoted_segment_syntax_suggest(seg: &str) -> String {
    // Simplified version for syntax-suggest
    let mut out = String::new();
    out.push_str("\x1b[0;42m\"");
    out.push_str(seg);
    out.push_str("\x1b[0;42m\"\x1b[m");
    out
}
