fn syntax_highlight(content: &str) -> Result<String, String> {
    let mut out = String::new();
    for line in content.split_inclusive('\n') {
        let has_nl = line.ends_with('\n');
        let line_content = if has_nl { &line[..line.len()-1] } else { line };
        out.push_str(&syntax_highlight_line(line_content));
        if has_nl { out.push('\n'); }
    }
    Ok(out)
}

fn syntax_highlight_line(line: &str) -> String {
    // Handle comment
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut comment_start: Option<usize> = None;
    for (idx, c) in line.chars().enumerate() {
        if escaped { escaped = false; continue; }
        if c == '\\' && !in_single { escaped = true; continue; }
        if in_single { if c == '\'' { in_single = false; } continue; }
        if in_double { if c == '"' { in_double = false; } continue; }
        if c == '\'' { in_single = true; continue; }
        if c == '"' { in_double = true; continue; }
        if c == '#' {
            if idx==0 { comment_start = Some(idx); break; }
            else {
                let prev = line.chars().nth(idx-1).unwrap_or(' ');
                if prev.is_whitespace() || prev == ';' || prev == '&' || prev == '|' || prev == '(' {
                    comment_start = Some(idx); break;
                }
            }
        }
    }
    let (code_part, comment_part) = if let Some(cs) = comment_start {
        (&line[..cs], &line[cs..])
    } else { (line, "") };
    let highlighted_code = syntax_highlight_code_part(code_part);
    if !comment_part.is_empty() {
        format!("{}{}\x1b[0;1;3;38;2;120;144;96m{}\x1b[m", highlighted_code, "", comment_part)
    } else {
        highlighted_code
    }
}

fn syntax_highlight_code_part(code: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    let mut at_command_start = true;
    let mut seen_assignment = false;
    let mut after_export_local = false;
    let mut in_single = false;
    let mut in_double = false;
    let mut in_ansi = false;
    let mut escaped = false;
    let mut in_double_bracket = false;
    let mut case_next_no_quote = false;

    while i < chars.len() {
        let c = chars[i];
        if escaped { out.push(c); escaped = false; i+=1; continue; }
        if c == '\\' && !in_single { out.push(c); escaped = true; i+=1; continue; }
        if in_single {
            // Single quoted string: need to find closing '
            if c == '\'' {
                // Find start of this single quoted string? We already entered single quote earlier, but now we are inside
                // Actually in_single handling is for when we are already inside single quote from earlier char
                // We output the whole single quoted string at once when we enter, so this branch shouldn't happen for inside? 
                // For safety, handle
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str("\x1b[0;38;2;255;204;85m");
                out.push_str(&s);
                out.push_str("\x1b[m");
                i=j;
                in_single=false;
                continue;
            }
            out.push(c); i+=1; continue;
        }
        if in_ansi {
            if c == '\'' {
                // Find end of ansi-c
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str("\x1b[0;38;2;255;128;0m");
                out.push_str(&s);
                out.push_str("\x1b[m");
                i=j;
                in_ansi=false;
                continue;
            }
            out.push(c); i+=1; continue;
        }
        if in_double {
            if c == '"' { out.push_str("\x1b[0;38;2;255;0;0m\"\x1b[m"); in_double=false; i+=1; continue; }
            // Inside double quotes: handle $ and escaped
            if c == '\\' {
                if i+1 < chars.len() {
                    let next = chars[i+1];
                    if next == '$' || next == '"' || next == '\\' || next == '`' {
                        out.push_str("\x1b[0;1;38;2;255;0;128m");
                        out.push('\\'); out.push(next);
                        out.push_str("\x1b[0;38;2;255;0;0m");
                        i+=2; continue;
                    }
                }
            }
            if c == '$' {
                if i+1 < chars.len() && chars[i+1] == '{' {
                    if let Some(end) = find_matching_brace(&chars, i+1) {
                        let s: String = chars[i..=end].iter().collect();
                        out.push_str("\x1b[0;38;2;63;127;207m");
                        out.push_str(&s);
                        out.push_str("\x1b[0;38;2;255;0;0m");
                        i=end+1; continue;
                    }
                } else if i+1 < chars.len() {
                    let next = chars[i+1];
                    if "*@#?$!0123456789".contains(next) || is_identifier_start(next) {
                        let mut j = i+1;
                        if is_identifier_start(next) {
                            j+=1;
                            while j < chars.len() && is_identifier_char(chars[j]) { j+=1; }
                        } else { j+=1; }
                        let var_str: String = chars[i..j].iter().collect();
                        out.push_str("\x1b[0;38;2;63;127;207m");
                        out.push_str(&var_str);
                        out.push_str("\x1b[0;38;2;255;0;0m");
                        i=j; continue;
                    }
                }
            }
            out.push(c); i+=1; continue;
        }
        if c == '\'' {
            if i>0 && chars[i-1] == '$' {
                // $'...
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                let s: String = chars[i-1..j.min(chars.len())].iter().collect();
                // Need to output $ plus colored '...'
                // We already output $ earlier? Actually when we encounter ' after $, we are at '
                // The $ was already output as part of previous handling? For simplicity, output whole
                out.pop(); // remove $ that was already output? This is messy
                out.push_str("\x1b[0;38;2;255;128;0m");
                out.push_str(&s);
                out.push_str("\x1b[m");
                i=j;
                continue;
            } else {
                // Single quoted
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str("\x1b[0;38;2;255;204;85m");
                out.push_str(&s);
                out.push_str("\x1b[m");
                i=j;
                continue;
            }
        }
        if c == '"' {
            out.push_str("\x1b[0;38;2;255;0;0m\"");
            out.push_str("\x1b[0;38;2;255;0;0m");
            in_double=true;
            i+=1; continue;
        }
        if c == '`' {
            // Backtick
            let mut j = i+1;
            while j < chars.len() && chars[j] != '`' { j+=1; }
            if j < chars.len() { j+=1; }
            let s: String = chars[i..j.min(chars.len())].iter().collect();
            // Inside backticks, highlight recursively
            out.push('`');
            let inner = if s.len()>=2 { &s[1..s.len()-1] } else { "" };
            let inner_hl = syntax_highlight_code_part(inner);
            out.push_str(&inner_hl);
            out.push('`');
            i=j; continue;
        }
        if c == ';' || c == '&' || c == '|' || c == '(' || c == ')' {
            out.push(c);
            at_command_start = true;
            seen_assignment = false;
            after_export_local = false;
            // Handle [[ and ]]
            if c == '[' && i+1 < chars.len() && chars[i+1] == '[' {
