                // Actually in_single handling is for when we are already inside single quote from earlier char
                // We output the whole single quoted string at once when we enter, so this branch shouldn't happen for inside? 
                // For safety, handle
                let mut j = i+1;
                while j < chars.len() && chars[j] != '\'' { j+=1; }
                if j < chars.len() { j+=1; }
                let s: String = chars[i..j.min(chars.len())].iter().collect();
                out.push_str("\x1b[0;38;2;255;204;85m");
                out.push_str(&s);
                out.push_str("\x1b[m");
